/* Master glossary. Schema: CLAUDE.md §9.
   { term, definition, category, chapters: [slug, ...] }
   Appended to as chapters are built — check for name collisions before adding a new term;
   extend an existing entry's `chapters` array instead of duplicating.

   Merge note (GATE-1 reference set): chapter 01's proposed "Offboarding (deprovisioning)" was merged
   into chapter 02's "Deprovisioning" entry (same concept, chapter 02 owns the lifecycle-stage framing)
   instead of being added as a second, duplicate entry — see BUILD_STATUS.md. */
window.GLOSSARY = [
  { term: "IAM (Identity and Access Management)", definition: "The discipline and category of software responsible for answering two questions on behalf of every connected application: who is this (authentication), and what are they allowed to do (authorization) — solved once, centrally, instead of separately by each application.", category: "IAM Foundations", chapters: ["what-is-iam"] },
  { term: "Authentication (AuthN)", definition: "The process of proving who a user or system is, typically via a password, one-time code, hardware key, or combination of factors. Answers \"who are you?\" Full depth in chapter 3, including why a system can authenticate someone perfectly and still make the wrong access-control decision right after — authentication and authorization are evaluated as independent steps, not one checkbox.", category: "IAM Foundations", chapters: ["what-is-iam", "authn-authz-accounting"] },
  { term: "Authorization (AuthZ)", definition: "The process of deciding what an already-authenticated identity is permitted to do. Answers \"what can you do, now that I know who you are?\" A system can authenticate correctly and still authorize incorrectly — they are distinct problems. Full depth in chapter 3; a common real-world bug is checking only \"is this user authenticated\" instead of \"is this specific user allowed to act on this specific resource.\"", category: "IAM Foundations", chapters: ["what-is-iam", "authn-authz-accounting"] },
  { term: "Single Sign-On (SSO)", definition: "A property of centralized authentication where one login session is usable across multiple connected applications, without re-entering credentials for each one. Mechanically: the authentication act happens once against a shared Identity Provider (IdP); the browser carries a session the IdP recognizes, and each connected application (SP/RP) establishes its own trust in that result via a redirect-and-assertion handshake with the same IdP, rather than the user re-typing credentials app by app or the apps sharing a password. Protocol-specific mechanics (OAuth/OIDC/SAML) are covered in Part III; Keycloak's realm-level session implementation is covered in chapter 29.", category: "IAM Foundations", chapters: ["what-is-iam", "sso-and-federation"] },
  { term: "Centralized authentication", definition: "The practice of delegating login, credential storage, and session management to one shared system that every application trusts, instead of each application implementing its own.", category: "IAM Foundations", chapters: ["what-is-iam"] },
  { term: "Identity broker", definition: "An IAM system acting as an intermediary that delegates the act of authentication to an external identity provider (e.g. Google, a corporate SAML IdP) that the user already has an independent account with, and translates the result into a form the connecting applications understand — without those applications needing to integrate with the external provider directly, and without the broker ever storing or managing the user's credential at that external IdP. Contrast with federation, which reuses an existing directory rather than delegating a single login event. Full depth in chapter 7; implemented in chapter 31.", category: "IAM Foundations", chapters: ["what-is-iam", "sso-and-federation"] },
  { term: "Federation (identity federation)", definition: "Connecting an IAM system to an existing external identity store or directory (such as an LDAP directory or Active Directory) so its existing population of accounts can be reused — checked via operations like an LDAP bind — without migrating every user into the IAM system or asking an external IdP to authenticate them. Contrast with identity brokering, which delegates a single login event to an external IdP rather than reusing a directory the organization already runs. Full depth in chapter 7; implemented in chapter 32.", category: "IAM Foundations", chapters: ["what-is-iam", "sso-and-federation"] },
  { term: "Self-service (account management)", definition: "Capability letting end users manage their own account — resetting a password, updating a profile, reviewing active sessions — without filing a help-desk request.", category: "IAM Foundations", chapters: ["what-is-iam", "users-and-credentials"] },
  { term: "Admin console", definition: "A generic term for the administrative interface an IAM system provides for managing users, applications, and policy without touching the underlying database directly. Keycloak's Admin Console is a web UI (reachable at /admin) backed entirely by the Admin REST API — every click it performs is a REST call any script could make instead (this course verifies that equivalence directly via kcadm.sh throughout Parts IV-V). Per Keycloak's own Server Administration Guide: the top-left 'Current realm' selector shows which realm you're currently managing and lets you switch; its dropdown includes a 'Create realm' button that opens a form with a single required realm-name field — submitting it makes the new realm the current realm automatically, and generates a key pair and self-signed certificate for it. Below the realm selector, the left nav groups screens under 'Manage' (users, groups, sessions, events) and 'Configure' (realm settings, clients, roles, identity providers, authentication). The exact screen layout above is drawn from Keycloak's current official documentation, not personally screenshot-verified in this course (no browser tool is available in this environment) — every underlying mechanism it describes was independently confirmed via the Admin REST API through kcadm.sh.", category: "IAM Foundations", chapters: ["what-is-iam", "installing-keycloak"] },
  { term: "Extensibility (plugin architecture)", definition: "An IAM system's ability to be customized — custom authentication steps, custom data sources, custom branding — via a defined plugin interface rather than forking the product's source code. Keycloak's SPI architecture is covered in Part VIII.", category: "IAM Foundations", chapters: ["what-is-iam", "themes-and-branding"] },
  { term: "Audit trail", definition: "The recorded output of accounting — a consistent, centrally recorded log of authentication and access events (logins, permission changes, admin actions) that lets an organization answer \"who accessed what, and when.\" Audit, more precisely, is the separate, later activity of reviewing that output (a compliance review, an incident investigation); the audit trail is what accounting produces for audit to consume. Full depth in chapter 3 (as part of AAA, including a note on an industry terminology ambiguity around \"accounting\") and chapter 28 (Keycloak's event logging).", category: "IAM Foundations", chapters: ["what-is-iam", "authn-authz-accounting"] },
  { term: "Compliance-readiness", definition: "The degree to which an IAM system's authentication (including MFA), authorization, and accounting/audit-logging capabilities already satisfy what regulatory and contractual frameworks demand, reducing the work needed to pass an audit. In practice, no major framework — GDPR, SOC 2's Trust Services Criteria, the HIPAA Security Rule, PCI-DSS, or ISO/IEC 27001 — invents new IAM theory: each independently demands authentication, authorization (often phrased as least privilege or need-to-know), and accounting (phrased as audit controls, logging, or monitoring) under its own vocabulary and numbering. Full framework-by-framework treatment in chapter 11.", category: "IAM Foundations", chapters: ["what-is-iam", "compliance-for-iam"] },
  { term: "Workforce IAM", definition: "IAM focused on managing an organization's own employees, contractors, and the service accounts they operate — a bounded, HR-backed population (identity count roughly tracks headcount, and most identities are tied to a joiner-mover-leaver record, chapter 10). Covers SSO into internal and SaaS business applications, directory federation, and role/group-based authorization. Distinct from CIAM (external, self-registering, consumer-scale populations) and from PAM (the smaller, higher-risk slice of privileged/admin accounts within the workforce). Full market-category depth, including vendor comparison, in chapter 12.", category: "IAM Foundations", chapters: ["what-is-iam", "iam-market-landscape"] },
  { term: "CIAM (Customer Identity and Access Management)", definition: "IAM focused on managing external, customer-facing identities — an unbounded, self-registering population (anyone can sign up any time) at consumer scale, typically in the millions rather than hundreds or thousands. Prioritizes social login, progressive profiling, login-page branding/conversion impact, and consumer-grade uptime over directory federation. The buyer is usually the product organization, not IT, unlike workforce IAM. Distinct from Workforce IAM (an organization's own bounded, HR-backed population). Full market-category depth, including vendor comparison, in chapter 12.", category: "IAM Foundations", chapters: ["what-is-iam", "iam-market-landscape"] },
  { term: "Multi-factor authentication (MFA)", definition: "Requiring proof from two or more different factor categories to authenticate — typically something you know (a password) combined with something you have (a hardware key, an authenticator app) or something you are (biometrics). Two proofs from the same category (e.g. a password plus a security question) are not genuine MFA. Full treatment of factor categories, OTP mechanics, WebAuthn/FIDO2/passkeys, and risk-based/step-up authentication in chapter 5; Keycloak's MFA/OTP configuration in chapter 30.", category: "IAM Foundations", chapters: ["what-is-iam", "authentication-factors-mfa", "authentication-flows"] },
  { term: "Single point of failure (IAM context)", definition: "A risk introduced by centralizing authentication: if the shared IAM system is unavailable, login for every connected application is unavailable too, unlike independent per-app login systems which fail separately.", category: "IAM Foundations", chapters: ["what-is-iam"] },

  { term: "Identity", definition: "The complete record representing a particular person, service, or device within a system: the bundle that ties an identifier, one or more credentials, and a set of attributes together under one entity.", category: "Core concepts", chapters: ["identity-fundamentals"] },
  { term: "Identifier", definition: "The unique value used to look an identity up within a given namespace — a username, email address, or employee ID. An identifier doesn't need to be secret; it only needs to be unique enough to pick one identity out from the rest.", category: "Core concepts", chapters: ["identity-fundamentals", "users-and-credentials"] },
  { term: "Credential", definition: "Evidence presented to prove control of an identifier — a password, a one-time code, a private key, a fingerprint. Credentials can be rotated or replaced without changing who the identity is.", category: "Core concepts", chapters: ["identity-fundamentals", "users-and-credentials"] },
  { term: "Attribute", definition: "A fact recorded about an identity that isn't itself proof of anything — department, job title, phone number, subscription tier. Attributes describe the identity; they don't authenticate it.", category: "Core concepts", chapters: ["identity-fundamentals", "users-and-credentials"] },
  { term: "Principal", definition: "The entity being identified — the real-world person, service, or device an identity refers to, independent of any particular login session.", category: "Core concepts", chapters: ["identity-fundamentals"] },
  { term: "Subject", definition: "A principal as represented inside an active security context, such as a signed token or a live session. The same principal produces a new subject every time it authenticates.", category: "Core concepts", chapters: ["identity-fundamentals"] },
  { term: "Digital identity", definition: "The electronic representation of a principal inside a system — in practice, the identity record (identifier + credentials + attributes) that stands in for a real-world person, service, or device.", category: "Core concepts", chapters: ["identity-fundamentals"] },
  { term: "Identity lifecycle", definition: "The generalized sequence an identity moves through over time: create, activate, modify, suspend, and (eventually) delete. Vendor products implement this sequence with their own screens and states, but the stages themselves are the same everywhere.", category: "Identity lifecycle", chapters: ["identity-fundamentals", "users-and-credentials"] },
  { term: "Provisioning", definition: "The act of creating an identity and granting it the initial access it needs. As a lifecycle stage (chapter 2) this is a single event; chapter 10 covers the surrounding governance discipline — access reviews, segregation of duties, and the Joiner-Mover-Leaver (JML) vocabulary — that keeps checking whether what was provisioned is still correct long after the provisioning event itself is over.", category: "Identity lifecycle", chapters: ["identity-fundamentals", "identity-governance"] },
  { term: "Deprovisioning", definition: "The act of removing or disabling an identity's access, typically at the end of its lifecycle — for example, when an employee leaves. With centralized IAM, this collapses into a single action (disabling one identity) instead of chasing down access across every application individually. As a lifecycle stage (chapter 2) this is a single event; chapter 10 covers what happens when that event is missed — an orphaned account, an identity whose owner has left but whose access was never actually removed — and why periodic access review exists as a backstop for exactly that failure mode, not just a nice-to-have on top of working deprovisioning.", category: "Identity lifecycle", chapters: ["identity-fundamentals", "what-is-iam", "identity-governance"] },
  { term: "Service account", definition: "A non-human identity created for an application or automated process to authenticate with, rather than for a person. Typically long-lived and often over-privileged if not reviewed regularly.", category: "Identity types", chapters: ["identity-fundamentals"] },
  { term: "Machine identity", definition: "An identity that represents a device, server, or piece of infrastructure rather than a person — for example, a certificate-backed identity for a server. Overlaps with, but isn't identical to, a service account.", category: "Identity types", chapters: ["identity-fundamentals"] },
  { term: "Workload identity", definition: "An identity assigned to a running piece of software — a container, function, or process — so it can authenticate to other services without embedding a long-lived secret in its code. A modern refinement of the machine-identity idea, common in cloud and Kubernetes environments.", category: "Identity types", chapters: ["identity-fundamentals"] },
  { term: "Human identity", definition: "An identity that represents a person — an employee, customer, patient, or clinician — as opposed to a service, device, or workload.", category: "Identity types", chapters: ["identity-fundamentals"] },
  { term: "Self-registration", definition: "An identity lifecycle entry point where the principal creates their own identity through a signup form, rather than an administrator creating it for them. The federated/brokered variant, where the identity is instead created automatically from an external identity provider's data, is covered in chapter 7.", category: "Identity lifecycle", chapters: ["identity-fundamentals"] },
  { term: "Northwind Apps", definition: "One of this course's three running case-study organizations: a B2B SaaS company whose identity population is split between its own internal staff and the employees of the business customers who use its product.", category: "Case-study orgs", chapters: ["identity-fundamentals"] },
  { term: "Riverside Health", definition: "One of this course's three running case-study organizations: a hospital network operating under HIPAA, whose identity population includes clinician workforce identities and patient identities using a patient portal.", category: "Case-study orgs", chapters: ["identity-fundamentals"] },
  { term: "Meridian Trust", definition: "One of this course's three running case-study organizations: a retail bank operating under PCI-DSS, whose identity population includes bank employees and retail customers, and whose IAM work emphasizes step-up authentication and fraud-aware access decisions.", category: "Case-study orgs", chapters: ["identity-fundamentals"] },

  { term: "Accounting", definition: "The third formal part of the AAA model (Authentication, Authorization, Accounting): the act of recording identity and access events — logins, permission checks, administrative changes — as structured, timestamped data, continuously and in real time as they occur. Distinct from audit, which is the later activity of reviewing those records. Note: in classic network-access-control contexts (RADIUS, dial-up/VPN access control) \"accounting\" leans toward usage metering for billing; in general modern IAM usage the word has broadened to mean security-event logging for audit and forensic purposes. Keycloak implements this as its realm Events subsystem (chapter 28).", category: "IAM Foundations", chapters: ["authn-authz-accounting"] },

  { term: "Directory service", definition: "A specialized, read-optimized data store for records about people, systems, and resources, organized hierarchically and built for fast lookups rather than transactions. Most organizations already have one — frequently Active Directory — before they ever adopt a dedicated IAM product.", category: "Directory services", chapters: ["directory-services"] },
  { term: "X.500", definition: "An ITU-T standard from the 1980s defining a comprehensive, heavyweight model for directories and the protocols to access them. LDAP's data model is inherited from X.500, though LDAP itself runs over plain TCP/IP.", category: "Directory services", chapters: ["directory-services"] },
  { term: "LDAP (Lightweight Directory Access Protocol)", definition: "A lightweight, TCP/IP-based protocol for accessing directories that follow the X.500 data model. It is the protocol most real directory products — including Active Directory — expose for interoperability, and the one Keycloak speaks for user federation (chapter 32).", category: "Directory services", chapters: ["directory-services"] },
  { term: "Directory Information Tree (DIT)", definition: "The hierarchical structure an LDAP directory's data is organized into — a tree of entries, typically shaped around an organization's domain and internal structure.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Entry (directory entry)", definition: "One record inside a Directory Information Tree — a person, group, or device. Roughly analogous to a database row, except entries live in a tree rather than a flat table.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Distinguished Name (DN)", definition: "The full, unique path to one entry from the root of the Directory Information Tree — an entry's unique address inside the directory. Moving an entry to a different position in the tree can change its DN.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Relative Distinguished Name (RDN)", definition: "The single component of a Distinguished Name that distinguishes an entry from its siblings under the same parent. A DN is a chain of RDNs read from the entry up to the root.", category: "Directory services", chapters: ["directory-services"] },
  { term: "objectClass", definition: "A declaration on a directory entry of what kind of thing it is and which attributes it's allowed or required to carry — e.g. person, organizationalPerson, inetOrgPerson. An entry can carry more than one objectClass.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Bind operation", definition: "The LDAP operation where a client presents a Distinguished Name and a credential and the directory checks whether the credential is correct for that entry. A simple bind is, functionally, an authentication attempt phrased in LDAP's own terms — but a successful bind proves nothing about authorization.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Simple bind", definition: "A bind operation performed with a Distinguished Name and a plaintext (or TLS-protected) password — the most common way an LDAP client authenticates against a directory.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Anonymous bind", definition: "A bind operation performed without presenting any credential, used for unauthenticated read-only lookups. Left enabled unintentionally on a production directory, it is a real security exposure.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Active Directory (AD)", definition: "Microsoft's directory product and the dominant store for enterprise workforce identities. It exposes an LDAP interface among others, while also using its own native mechanisms (such as Kerberos) for day-to-day authentication.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Domain (AD domain)", definition: "A security and administrative boundary in Active Directory — a set of users, computers, and policies managed together, identified by a DNS-style name such as riversidehealth.local.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Organizational Unit (OU)", definition: "A container within an Active Directory domain used to group users, computers, or groups for the purpose of applying policy and delegating administration — the rough AD analogue of a generic LDAP ou entry.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Domain Controller (DC)", definition: "A server that holds a copy of an Active Directory domain's directory data and services authentication requests against it — the directory server itself, in AD's vocabulary.", category: "Directory services", chapters: ["directory-services"] },
  { term: "Kerberos", definition: "A ticket-based authentication protocol and Active Directory's native mechanism for day-to-day login, distinct from a plain LDAP bind. Deliberately not covered in depth in this course — only its existence and role need to be known here.", category: "Directory services", chapters: ["directory-services"] },

  { term: "Knowledge factor", definition: "An authentication factor based on something the user knows, such as a password, PIN, or security question. Vulnerable to phishing, guessing, reuse, and shoulder-surfing — and combining two knowledge factors does not produce genuine MFA.", category: "Authentication factors", chapters: ["authentication-factors-mfa"] },
  { term: "Possession factor", definition: "An authentication factor based on something the user has, such as a phone running an authenticator app, a hardware security key, or a badge. Vulnerable to theft or loss, and to SIM-swap attacks specifically for SMS-based possession factors.", category: "Authentication factors", chapters: ["authentication-factors-mfa"] },
  { term: "Inherence factor", definition: "An authentication factor based on something the user is, such as a fingerprint, face, iris, or voice. Unlike a credential, an inherence factor cannot be rotated if its stored template is compromised, which makes that kind of incident categorically different from a leaked password.", category: "Authentication factors", chapters: ["authentication-factors-mfa"] },
  { term: "Context/behavior signal", definition: "Information about the situation surrounding a login attempt — device, location, network, typing rhythm, time of day — rather than a traditional proof of identity. Not a classical authentication factor on its own; used as input to risk-based and adaptive authentication decisions.", category: "Authentication factors", chapters: ["authentication-factors-mfa"] },
  { term: "OTP (One-Time Password)", definition: "A short, single-use code generated from a shared secret, used as a possession-factor proof. The two standard variants, TOTP and HOTP, differ only in what moving factor advances the code.", category: "OTP mechanics", chapters: ["authentication-factors-mfa"] },
  { term: "TOTP (Time-based One-Time Password)", definition: "An OTP variant (RFC 6238) whose moving factor is the current time, rounded to a fixed step (commonly 30 seconds) — the code changes automatically as time passes. Requires the device and server clocks to stay reasonably synchronized.", category: "OTP mechanics", chapters: ["authentication-factors-mfa"] },
  { term: "HOTP (HMAC-based One-Time Password)", definition: "An OTP variant (RFC 4226) whose moving factor is a counter that increments each time a code is consumed, rather than the clock. Can desync from the server if a code is generated but never actually used.", category: "OTP mechanics", chapters: ["authentication-factors-mfa"] },
  { term: "Moving factor", definition: "The changing input — current time for TOTP, an incrementing counter for HOTP — that both the device and the server combine with a shared secret to independently compute the same one-time code, without needing to transmit the secret again.", category: "OTP mechanics", chapters: ["authentication-factors-mfa"] },
  { term: "WebAuthn", definition: "A W3C web standard providing a browser-level API for public-key-based authentication: a device generates a public/private key pair at registration, the private key never leaves the device, and the server verifies challenge signatures using the public key. The mechanism behind passkeys and hardware security key logins.", category: "Passwordless & FIDO2", chapters: ["authentication-factors-mfa"] },
  { term: "FIDO2", definition: "The broader family of standards that WebAuthn belongs to, covering how a browser or platform communicates with an authenticator device to perform public-key-based authentication.", category: "Passwordless & FIDO2", chapters: ["authentication-factors-mfa"] },
  { term: "Passkey", definition: "The user-facing name for a FIDO2/WebAuthn credential designed to sync across a person's own devices via their platform account, so using it feels like an ordinary login rather than carrying a separate security key.", category: "Passwordless & FIDO2", chapters: ["authentication-factors-mfa"] },
  { term: "Authenticator (WebAuthn/FIDO2)", definition: "The device or module — a phone, a hardware security key, a platform's built-in secure element — that holds a WebAuthn/FIDO2 private key and performs the signing operation, without ever exposing that key to the browser, the server, or the user.", category: "Passwordless & FIDO2", chapters: ["authentication-factors-mfa"] },
  { term: "Phishing-resistant authentication", definition: "An authentication method that cannot be defeated by tricking a user into entering credentials or codes on a fake site, because the proof itself (e.g. a WebAuthn signature) is cryptographically bound to the real site's origin and has nothing a human can be tricked into copying or typing. Typed passwords and OTP codes do not have this property; WebAuthn/FIDO2/passkeys do.", category: "Passwordless & FIDO2", chapters: ["authentication-factors-mfa", "iam-threat-landscape"] },
  { term: "Risk-based authentication (adaptive authentication)", definition: "An authentication strategy that evaluates contextual signals — device, location, action sensitivity — to raise or lower how much proof is required for a given login or action, instead of applying the same fixed requirement every time.", category: "Risk-based authentication", chapters: ["authentication-factors-mfa"] },
  { term: "Step-up authentication", definition: "Demanding one additional authentication factor mid-session, triggered by an elevated-risk signal such as a sensitive action or an unfamiliar device, rather than on a fixed schedule. Layered on top of an already-successful login, not a replacement for it.", category: "Risk-based authentication", chapters: ["authentication-factors-mfa", "authentication-flows"] },
  { term: "Authenticator Assurance Level (AAL)", definition: "NIST SP 800-63B's tiered classification (AAL1-AAL3) of how strong an authentication method's combined factors are, used as a reference point when deciding what level of proof a given risk or compliance requirement calls for.", category: "Risk-based authentication", chapters: ["authentication-factors-mfa"] },

  { term: "Access Control List (ACL)", definition: "An authorization model that attaches permissions directly to a resource, listing exactly which subjects can do what to it. Simple to reason about for one resource at a time, but scales poorly as roughly N resources × M subjects of entries to maintain.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Role-Based Access Control (RBAC)", definition: "An authorization model where permissions attach to roles rather than directly to subjects, and subjects are assigned to one or more roles. Scales well for stable job functions; degrades into \"role explosion\" when access depends on conditions that aren't really job functions. Keycloak's realm and client roles are a direct implementation (chapter 23).", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Role explosion", definition: "The failure mode of an RBAC system where access conditions that aren't really distinct job functions get forced into roles anyway, producing a long list of near-duplicate, hard-to-reason-about roles instead of a small, stable set.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Attribute-Based Access Control (ABAC)", definition: "An authorization model that computes the access decision at request time from attributes of the subject, resource, and environment, rather than from a pre-assigned role or a static list. Puts the general Attribute concept (chapter 2) directly to work as live input to an access decision.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Policy-Based Access Control (PBAC)", definition: "An authorization model where access decisions are made by evaluating explicit, often centrally managed policy rules — frequently combining multiple attributes and conditions in one rule. Heavily overlaps with ABAC in practice, since most policies are evaluated over attributes; the literature does not draw a crisp, universal line between the two.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Relationship-Based Access Control (ReBAC)", definition: "An authorization model that bases access decisions on relationships between subjects and resources, modeled as a graph — e.g. \"is the owner of\" or \"is on the care team for\" — rather than on roles or attribute values alone. Fits fine-grained, frequently changing access patterns that roles and attributes alone express poorly. Keycloak's Authorization Services can express relationship-flavored policies on top of its resource/scope model (chapters 37-38).", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Zero Trust", definition: "The security principle of \"never trust, always verify\": no request is trusted by default just because it came from inside a network perimeter or from an already-authenticated session — every request to a protected resource is independently verified. A cross-cutting principle that applies regardless of which authorization model (ACL/RBAC/ABAC/PBAC/ReBAC) is in use underneath.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Least privilege", definition: "The security principle of granting a subject only the minimum access needed to do its job, for only as long as it's needed, rather than standing access granted broadly \"just in case.\" Applies across every authorization model, not as a model of its own.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Permission", definition: "A specific allowed action on a specific resource (or class of resource) — the unit of access that an authorization model attaches to a subject, directly (ACL), through a role (RBAC), or computed from a decision (ABAC/PBAC/ReBAC).", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Role", definition: "A named bundle of permissions, assigned to subjects rather than defining permissions per subject directly. The unit of indirection RBAC introduces between subjects and the permissions they hold. In Keycloak this is implemented as two scoped role types — a realm role (visible to every client in the realm) and a client role (a namespace dedicated to one specific client) — either of which can be assigned directly to a user or inherited via group membership, and either of which can be a composite role that transitively grants other roles it's \"associated with.\"", category: "Authorization models", chapters: ["authorization-models", "roles-and-groups"] },
  { term: "Policy engine", definition: "A system (often standalone) that evaluates explicit policy rules against a request to produce an allow/deny authorization decision, letting policies be authored, versioned, and audited independently of the applications that call them — the typical infrastructure a PBAC approach is built on.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Resource scope (authorization)", definition: "The specific object or boundary (a tenant, a document, a patient record) that a permission or role assignment applies to. A role check that verifies only \"does this subject hold role X\" without also verifying the resource scope it applies to is a common and serious RBAC implementation bug.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Relationship graph", definition: "A data structure modeling subjects and resources as nodes connected by labeled relationship edges (e.g. \"owns,\" \"is on the care team for\"), which a ReBAC system traverses at access-decision time to determine whether a subject's relationship to a resource grants access.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Account-risk attribute", definition: "An attribute recording how risky a given account is judged to be (e.g. new, flagged, high-value), used as one input to an ABAC decision such as how large a transaction a teller may approve against that account without further escalation.", category: "Authorization models", chapters: ["authorization-models"] },
  { term: "Care team relationship", definition: "A ReBAC relationship type recording which clinicians are currently authorized to access a specific patient's records because they are actively treating that patient — changing as patients are admitted, transferred, and discharged, and used in place of a blanket \"clinician\" role to decide chart access.", category: "Authorization models", chapters: ["authorization-models"] },

  { term: "Identity Provider (IdP)", definition: "The system in an SSO, brokering, or federation relationship that holds credentials, performs authentication, and asserts the user's identity to another system — a role name shared across SAML, OIDC, and OAuth terminology.", category: "SSO & Federation", chapters: ["sso-and-federation"] },
  { term: "Service Provider (SP)", definition: "SAML's name for the application that relies on an external IdP's assertion instead of authenticating the user itself. Refers to the same role as OIDC's Relying Party (RP) — the two terms are not different roles, just different protocols' vocabulary for one role.", category: "SSO & Federation", chapters: ["sso-and-federation"] },
  { term: "Relying Party (RP)", definition: "OpenID Connect's name for the application that relies on an external IdP's assertion instead of authenticating the user itself. Refers to the same role as SAML's Service Provider (SP) — the two terms are not different roles, just different protocols' vocabulary for one role.", category: "SSO & Federation", chapters: ["sso-and-federation"] },
  { term: "Trust (IdP/SP-RP trust)", definition: "The pre-configured agreement that lets an IdP and a relying application accept each other's messages: shared metadata describing endpoints and capabilities, certificates/signing keys to verify assertions weren't forged, and registered redirect URIs so login results can't be sent somewhere an attacker controls. Trust is configured in advance, never assumed. Full protocol-specific depth in chapter 15 (OIDC discovery) and chapter 17 (SAML metadata).", category: "SSO & Federation", chapters: ["sso-and-federation"] },
  { term: "JIT (just-in-time) provisioning", definition: "Automatically creating a local identity from an external IdP's or directory's data the first time a user successfully authenticates through brokering or federation, rather than an administrator pre-creating the account. This is the mechanism behind the \"federated/brokered creation\" entry point into the identity lifecycle's create stage (chapter 2) — everything downstream (modify, suspend, delete) proceeds exactly as it would for any other identity.", category: "SSO & Federation", chapters: ["sso-and-federation"] },
  { term: "Assertion", definition: "The message an Identity Provider sends to a relying application stating who the user is (and typically some attributes about them), after authenticating that user. The specific format and transport of an assertion differs by protocol (a SAML assertion vs. an OIDC ID token), but the conceptual role is the same across both. In SAML 2.0 specifically, an assertion is a signed XML <saml:Assertion> document with four key parts: a <saml:Subject> (a NameID plus a SubjectConfirmation tying the assertion to the specific browser exchange it was issued for), <saml:Conditions> (a NotBefore/NotOnOrAfter validity window plus an AudienceRestriction naming exactly which SP may accept it), a <saml:AuthnStatement> (when authentication happened and by what method), and an optional <saml:AttributeStatement> (arbitrary name/value user attributes). The whole assertion is wrapped in an XML digital signature the SP must validate against the IdP's trusted certificate — checking only that the HTTP response arrived over TLS is not the same as validating this signature.", category: "SSO & Federation", chapters: ["sso-and-federation", "saml2"] },
  { term: "Metadata (IdP/SP metadata)", definition: "A machine-readable description of an IdP's or SP/RP's endpoints and supported capabilities, exchanged so each side can configure itself to talk to the other correctly instead of guessing. One of the three ingredients of establishing trust between an IdP and a relying application. In SAML 2.0 specifically, this is an XML <EntityDescriptor> document: it names the entity's stable entityID, carries its signing (and sometimes encryption) certificate inside a <KeyDescriptor>, and lists concrete endpoint URLs per supported binding — an IdP's metadata lists its SingleSignOnService URLs inside an <IDPSSODescriptor>; an SP's metadata lists its AssertionConsumerService (ACS) URL inside an <SPSSODescriptor>. Compare OIDC's discovery document (chapter 15), which does the same job as JSON fetched live over HTTP rather than XML exchanged once during setup.", category: "SSO & Federation", chapters: ["sso-and-federation", "saml2"] },
  { term: "Redirect URI (registered)", definition: "A URL an application pre-registers with an IdP as a valid destination to send the browser back to after authentication. The IdP only redirects to registered URIs, preventing an attacker from redirecting a login result to a URL they control. One of the three ingredients of establishing trust between an IdP and a relying application; full mechanics in chapter 13 (OAuth 2.0 authorization code flow). Under OAuth 2.0 specifically, RFC 6749 §3.1.2.3 requires the authorization server to validate a submitted redirect_uri against the registered value using exact, simple string comparison — not a prefix, substring, or same-domain match — and §3.1.2.4 requires it to refuse to redirect at all on a mismatch rather than silently falling back to some other registered URI. This exact-match requirement is a real security control, not a formality: a looser match lets an attacker who controls any URL that merely resembles the registered one receive a legitimate user's authorization code and exchange it for tokens issued in that user's name. Chapter 13 verifies this concretely against a live authorization server — and found a public demo client that does NOT enforce this correctly, a live, reproducible finding (independently confirmed by the coordinator), used there as a cautionary, non-production example. Keycloak's own Valid Redirect URIs field enforces this same exact-match rule but documents a narrow extension: a trailing wildcard (https://host.com/path/*), with userinfo/path-traversal (/../) segments explicitly excluded from wildcard matching and the bare * wildcard explicitly warned against in production. Chapter 24 registers a path-scoped wildcard for exactly this reason.", category: "SSO & Federation", chapters: ["sso-and-federation", "oauth2-core", "clients-and-scopes"] },
  { term: "SSO session", definition: "The session an Identity Provider maintains for a browser after a successful login, tracked so that a later redirect from a different connected application is recognized without asking the user to re-authenticate. This session, not a shared password, is what makes SSO work. Keycloak implements this concretely at the realm level with two independent clocks: SSO Session Idle (an inactivity timeout — the session dies if unused longer than this) and SSO Session Max (an absolute ceiling regardless of activity), both configurable per realm (e.g. northwind-apps set these to 3,600s and 28,800s respectively in chapter 21, loosening idle for convenience while tightening max for the same underlying security reason). A third, independent, shorter-lived clock — Access Token Lifespan — governs individual bearer tokens minted during that session, not the session itself; a session commonly outlives many access-token refresh cycles. Full session-management depth (client sessions, offline sessions, concurrent-session limits) is chapter 29's subject.", category: "SSO & Federation", chapters: ["sso-and-federation", "realms"] },
  { term: "LDAP bind (federation context)", definition: "The operation an IAM system performs against an external directory (LDAP or Active Directory) to check a submitted credential, as part of identity federation — the directory, not the IAM system, remains the authoritative store for the credential. Introduced conceptually in chapter 4; implemented in chapter 32.", category: "SSO & Federation", chapters: ["sso-and-federation"] },
  { term: "Enterprise SSO", definition: "An arrangement where a B2B application's enterprise customer wants its own employees to sign in using the customer's own corporate Identity Provider, rather than a password issued by the application vendor. From the vendor's point of view, this is identity brokering: the vendor is the SP/RP, and the customer's corporate IdP is the external IdP being trusted.", category: "SSO & Federation", chapters: ["sso-and-federation"] },
  { term: "Social login", definition: "A specific, consumer-facing case of identity brokering where the external IdP is a large consumer identity provider such as Google or Microsoft, rather than a corporate/enterprise IdP. Covered conceptually here; Keycloak's social-login identity provider configuration is covered in chapter 31.", category: "SSO & Federation", chapters: ["sso-and-federation"] },

  { term: "Bearer token", definition: "A token whose only required proof of authorization is possession of the token itself — whoever holds and presents it can use it, with no built-in check that the presenter is the party it was originally issued to. If a bearer token is stolen, the thief can use it exactly as the real owner could, until it expires.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Claim", definition: "A key-value assertion carried inside a token that the issuer is vouching for — e.g. who the token is for, who issued it, when it expires, or what the subject is allowed to do. Purely conceptual here; the exact wire format (JWS/JWE/JWK) is chapter 16's subject.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Access token", definition: "A token presented to a resource server (an API) to prove an already-authenticated subject's authorization to use it, typically short-lived by design so a stolen copy stays useful for as little time as possible.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Refresh token", definition: "A longer-lived token used to obtain new access tokens without re-authenticating the principal from scratch. Its lifetime is a direct security/convenience trade-off: longer keeps users logged in with less friction, but gives a thief who steals it a longer usable path to new access tokens.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Refresh-token rotation", definition: "A mitigation for the revocation problem: keep access tokens very short-lived and use a refresh token (itself revocable, since refreshing typically involves a server-side check) to mint new ones — moving the \"can we still trust this\" check to a less frequent point rather than eliminating it.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Stateless authentication", definition: "An architecture where a token is self-contained and verifiable by any server with no database lookup required. Scales well across many independent servers with no shared session store, but makes early revocation hard — see the revocation problem.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Stateful authentication", definition: "An architecture where a short, opaque session identifier requires a server-side lookup against a shared store on every request. Trivially revocable (delete the server-side record), at the cost of needing that shared store reachable by every server.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Session (authentication session)", definition: "A server-side record of an authenticated subject's ongoing interaction, referenced by a short identifier the client holds (such as a cookie value) that is meaningless on its own without a server-side lookup. Full Keycloak session mechanics in chapter 29.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Session store", definition: "The shared, server-side data store that a stateful authentication system looks a session identifier up against on every request. Must be reachable by every server handling requests, which becomes its own piece of infrastructure to run and scale.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "The revocation problem", definition: "The genuine, unsolved-in-general tension that a stateless bearer token is valid until it expires, with no clean way to invalidate it early without reintroducing the server-side lookup statelessness exists to avoid. Managed with partial mitigations (short lifetimes, refresh rotation, introspection, key rotation), never fully solved.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Token lifetime", definition: "The configured validity window of a token, from issuance to expiry. Functions as a real security control under the revocation problem, not just a convenience setting — shorter lifetimes shrink how long a stolen token stays useful.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Token introspection", definition: "A mitigation for the revocation problem where a resource server calls back to the token issuer to ask whether a token is still valid, standardized by RFC 7662: a POST to an introspection endpoint with the token, authenticated as the calling party, returning a JSON body with an active boolean plus the token's claims if it's real (and almost nothing if it isn't, deliberately, to prevent fishing for valid tokens). Works, but reintroduces the server-side lookup that statelessness was meant to avoid — and its active result depends entirely on how the authorization server implements the check: for a reference token it's a real server-side lookup; for a self-contained JWT it typically only re-verifies the signature and expiry, which is why introspecting a 'revoked' JWT can still report active: true (confirmed live in chapter 14's revocation lab). Full mechanics in chapter 14.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions", "oauth2-extended"] },
  { term: "Signing-key rotation", definition: "Replacing the cryptographic key used to sign tokens, which invalidates every token signed with the old key at once. A blunt mitigation for the revocation problem — it revokes everything, not one specific token — but sometimes exactly the right tool, e.g. after a suspected key compromise. Mechanically: a verifier picks the right key for a given token via the token header's kid, matched against the issuer's JWKS response; rotation publishes a new key into JWKS before any token is signed with it, keeps the outgoing key listed in JWKS for an overlap period so tokens already signed with it remain verifiable, then removes the outgoing key once every token it signed has expired. Full JWS/JWKS mechanics in chapter 16.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions", "jwt-and-crypto"] },
  { term: "Issuer claim", definition: "A claim identifying which system vouches for a given token's contents — part of the trust basis a verifier relies on when accepting a token at all.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Audience claim", definition: "A claim identifying which service or resource server a token is meant to be used against, so a token issued for one API can't be silently reused against an unrelated one.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },
  { term: "Blast radius (token theft)", definition: "The scope and duration of damage a stolen credential or token can cause before it stops being useful — shrinking it (e.g. via short token lifetimes) is a core strategy for managing the revocation problem rather than solving it outright.", category: "Tokens & Sessions", chapters: ["tokens-and-sessions"] },

  { term: "Credential stuffing", definition: "Automated, large-scale reuse of username/password pairs leaked from other, unrelated sites' breaches against a login form, betting that some fraction of users reused the same credentials. The attacker never cracks or guesses anything — the credentials are already real.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Password reuse", definition: "Using the same password (or a trivial variation of it) across multiple unrelated accounts. The single behavior that makes credential stuffing effective: an attacker holding one site's breached password list can succeed against a different, unrelated site purely because of reuse.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Account takeover (ATO)", definition: "The end state of a successful credential-based attack: an attacker gains full, ongoing control of a legitimate user's account, typically able to change its password, email, or MFA settings and lock the real owner out.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Credential dump (breach corpus)", definition: "A large collection of username/password pairs exposed by a data breach, typically traded or published, and reused as raw input for credential-stuffing attacks against unrelated organizations.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Phishing", definition: "Tricking a user into disclosing credentials, or into approving a fraudulent MFA prompt, through a convincing fake login page, email, or message that impersonates someone or something the user trusts.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Spear phishing", definition: "Phishing targeted at a specific person or small group, using details about them (role, employer, recent events) to make the fraudulent message more convincing than a generic mass phishing email.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Adversary-in-the-middle (AiTM) phishing", definition: "A phishing technique that proxies the real login page live and relays whatever the victim submits — including a one-time MFA code — straight through to the real service in real time, which is why OTP-based MFA alone doesn't stop it.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Token theft", definition: "Stealing a valid bearer token — through a client-side vulnerability, misconfigured storage, or an intercepted network request — so it can be reused by someone other than its intended holder.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Token replay", definition: "Reusing a stolen token to authenticate again before it expires. Possible specifically because a bearer token proves nothing about who is presenting it — only that whoever holds it is trusted, which is the same property chapter 8's \"revocation problem\" is about.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Session hijacking", definition: "Stealing a session identifier or cookie to impersonate an already-authenticated session, as distinct from stealing a bearer token — the mechanism differs, but whoever holds the identifier is treated as the legitimate user until the session is invalidated.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "MFA fatigue (push bombing)", definition: "Repeatedly sending MFA approval push notifications to a target, often in rapid bursts or late at night, until a tired or confused user approves one by mistake. Requires the attacker to already hold a valid password; the bombing is how they get past the second factor.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Brute-force attack", definition: "Systematically trying many password guesses against a single account, as distinct from credential stuffing's use of already-known, previously breached credentials across many accounts.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Cross-site scripting (XSS)", definition: "A web application vulnerability that lets an attacker run arbitrary script in a victim's browser within the context of a trusted site, which can be used to read anything that browser session holds — including a bearer token kept in client-side storage.", category: "Threat landscape", chapters: ["iam-threat-landscape"] },
  { term: "Rate limiting", definition: "Capping how many requests (such as login attempts) a client can make in a given time window, used as a direct defense against credential stuffing and brute-force attacks. Configured in Keycloak as part of Brute Force Detection, covered in chapter 30.", category: "Security practices", chapters: ["iam-threat-landscape"] },
  { term: "Threat model", definition: "A structured description of who might attack a system, how, and what they'd gain, used to decide which defenses are worth building. This chapter's five threats are a starting threat model for any IAM deployment.", category: "Security practices", chapters: ["iam-threat-landscape"] },
  { term: "Attack surface (IAM context)", definition: "The set of points in an identity system an attacker could target — the login form, the MFA step, token issuance, and active sessions are the four this chapter maps threats onto.", category: "Security practices", chapters: ["iam-threat-landscape"] },
  { term: "Defense in depth (IAM context)", definition: "Layering multiple independent defenses (rate limiting, MFA, short token lifetimes, session revocation) so that defeating any one of them isn't enough on its own to compromise an account or session.", category: "Security practices", chapters: ["iam-threat-landscape"] },

  { term: "IGA (Identity Governance & Administration)", definition: "The discipline of provisioning, reviewing, and governing access over an identity's entire lifetime — making sure access is granted correctly, stays correct as circumstances change, and is provably correct when audited. A process discipline, distinct from the market category of tooling (SailPoint, Saviynt, etc.) that automates it, which chapter 12 covers separately.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Joiner-Mover-Leaver (JML)", definition: "The enterprise HR-driven vocabulary for chapter 2's generalized identity lifecycle, not a separate model: Joiner maps onto create+activate, Mover maps onto modify, and Leaver maps onto suspend+delete. Mover is the event most often implemented incorrectly — it should remove access tied to the old role, not just add access for the new one.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Access review (recertification)", definition: "A periodic, deliberate check of who has access to what, specifically to catch access that accumulated over time but is no longer justified — a finished project's leftover grant, an exception nobody revoked, or access stacked from a role change that was only ever additive. Exists because event-driven provisioning/deprovisioning only reacts to events someone remembered to trigger; a review is the scheduled act of looking anyway.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Segregation of Duties (SoD)", definition: "The principle that no single identity should hold two permissions whose combination lets that identity both carry out a sensitive action and be the only check on that same action — also called Separation of Duties. Neither permission alone is the problem; the danger is one identity holding both, which erases the independent check the second permission exists to provide.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Toxic combination", definition: "The specific set of permissions that creates a Segregation of Duties violation: the ability to both perform an action and be the sole check on that same action (e.g. creating a payment and approving it). Combinations can form later from two separately reasonable-looking grants, which is why they must be re-checked at every access review, not only at grant time.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Access certification", definition: "The specific act of a reviewer with the authority to judge it examining one entitlement and deciding whether to keep it or revoke it — the granular unit of work inside a recertification campaign.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Attestation (access certification)", definition: "A reviewer's formal, recorded confirmation that a specific access entitlement is still correct (or a recorded decision to revoke it) — what turns an access review from an informal glance into something an auditor can later verify actually happened.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Entitlement", definition: "A single, specific grant of access — one role, one group membership, one permission on one system — rather than everything an identity can do treated as one undifferentiated blob. Access reviews and certifications operate entitlement by entitlement so a reviewer can judge each grant on its own merits.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Recertification campaign", definition: "An organized, scheduled exercise bundling many individual access certifications together — typically all of one manager's reports, or all access to one sensitive system — reviewed on the same cadence (often quarterly or annual) so an organization has a complete, dated record rather than an ad-hoc patchwork of individual checks.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Stale access", definition: "Access an identity still holds but no longer has a legitimate business reason to hold — the specific thing access reviews exist to find, typically left over from a finished project, a prior role, or a temporary exception that was never revoked.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Role change (mover event)", definition: "The JML 'Mover' event: an identity changes team, job function, or location within the organization. Correctly implemented, it both grants access tied to the new role and removes access tied to the old role — treating it as purely additive (granting only) is the most common beginner mistake in identity governance. Reproduced for real against a running Keycloak realm in chapter 23: moving Northwind Apps' Priya from support-agent/Support to platform-engineer/Engineering required two grants (add-roles + group update) and two removals (remove-roles + group delete) — confirmed by re-querying role-mappings/realm and groups before and after and observing the old role/group were completely absent afterward, not merely superseded.", category: "Identity governance", chapters: ["identity-governance", "roles-and-groups"] },
  { term: "Compensating control", definition: "A documented, explicit alternative safeguard used when true Segregation of Duties isn't practically achievable (e.g. on a very small team) — such as a mandatory secondary review by someone outside the team, or an automatic flag on any transaction a conflicted identity both created and approved. An acknowledged trade-off, not a silent gap.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Four-eyes principle (dual control)", definition: "The underlying principle behind Segregation of Duties: a sensitive action requires two different people to look at it — one to perform it, one to independently verify it — before it takes effect. SoD is the organizational policy that structurally guarantees four-eyes rather than merely hoping for it.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Orphaned account", definition: "An account whose owning identity has left the organization or a role, but whose access was never actually removed — usually caused not by a missing deprovisioning process but by a missing trigger for an existing one. Periodic access review is the backstop that catches orphaned accounts when the event that should have deprovisioned them was missed.", category: "Identity governance", chapters: ["identity-governance"] },
  { term: "Rubber-stamping", definition: "The failure mode where a reviewer in a recertification campaign approves all entitlements without actually evaluating any of them individually, usually under time pressure. Produces a campaign record indistinguishable from a genuine review while providing none of its security value, since a review's benefit comes entirely from the judgment applied during it.", category: "Identity governance", chapters: ["identity-governance"] },

  { term: "GDPR", definition: "The EU's General Data Protection Regulation (Regulation (EU) 2016/679, in force since 25 May 2018), establishing data subject rights, a lawful-basis requirement, and data minimization obligations for anyone processing EU residents' personal data — including the accounts, profiles, and access logs an IAM system manages.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Data subject rights", definition: "The set of rights GDPR grants a person over their own personal data, including the right of access (Art. 15), erasure (Art. 17), and portability (Art. 20) — an IAM system must be able to locate, export, and delete a specific person's account and attribute data on request.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Right to erasure (right to be forgotten)", definition: "GDPR Article 17's right for a person to have their personal data deleted on request. For IAM systems this creates a real tension with audit-trail retention requirements; the common compromise is pseudonymizing rather than deleting log entries, with legal sign-off — not a universally clean resolution.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Data minimization", definition: "GDPR Article 5(1)(c)'s principle that only the personal data actually necessary for a stated purpose should be collected and retained — applies directly to which identity attributes an IAM system is allowed to ask for and keep.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Lawful basis for processing", definition: "GDPR Article 6's requirement that every instance of processing personal data have a documented legal justification (consent, contract necessity, legal obligation, legitimate interest, etc.) — an IAM system can't collect or retain identity attributes without one.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Data portability", definition: "GDPR Article 20's right for a person to receive their personal data in a structured, commonly used, machine-readable format and transmit it to another controller — relevant to how an IAM system exports a user's account data on request.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "SOC 2", definition: "An attestation framework, maintained by the AICPA, under which an independent auditor reports on an organization's controls against the Trust Services Criteria. The Security criterion — the only one required in every report — is the one most relevant to IAM, testing for evidence of access reviews, MFA enforcement, and logging.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Trust Services Criteria (TSC)", definition: "The AICPA's set of criteria categories (Security, Availability, Processing Integrity, Confidentiality, Privacy) that a SOC 2 report is audited against. The version currently in force is the 2017 criteria as revised in 2022; a further revision exists only as an exposure draft under public comment, not yet in force.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "HIPAA Security Rule", definition: "The U.S. regulation (45 CFR Part 164, Subpart C) setting administrative, physical, and technical safeguard requirements for protecting electronic protected health information (ePHI) — its technical safeguards (access control, unique user identification, audit controls, person/entity authentication) map directly onto this course's AAA model.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Minimum necessary standard", definition: "A HIPAA Privacy Rule requirement (45 CFR §164.502(b), §164.514(d)) — not the Security Rule, despite the two often being discussed together — that covered entities and business associates make reasonable efforts to limit PHI use, disclosure, and access requests to the minimum needed for the purpose at hand. Access control design is one of the main ways this is operationally implemented, concretely via relationship-based 'care team' access models.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Protected Health Information (PHI / ePHI)", definition: "Individually identifiable health information that HIPAA regulates; electronic PHI (ePHI) specifically is what the HIPAA Security Rule's safeguards protect.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "PCI-DSS", definition: "The Payment Card Industry Data Security Standard, maintained by the PCI Security Standards Council, mandatory for any organization that stores, processes, or transmits payment card data. Its Requirements 7, 8, and 10 are, respectively, least privilege, authentication/MFA, and accounting/audit trail under PCI-DSS's own numbering.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Cardholder Data Environment (CDE)", definition: "The scope boundary PCI-DSS defines: the systems, people, and processes that store, process, or transmit cardholder data, plus anything connected to them — PCI-DSS's access, authentication, and logging requirements apply within this boundary.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "ISO/IEC 27001", definition: "The international standard for information security management systems (ISMS). The current edition, ISO/IEC 27001:2022, reorganized its Annex A control list from the 2013 edition's 114 controls across 14 categories into 93 controls across 4 themes, renumbering access-control content into the 5.x/8.x ranges.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Annex A (ISO 27001)", definition: "The normative list of security controls an ISO/IEC 27001-certified organization selects from and documents in its Statement of Applicability. Its exact numbering differs materially between the 2013 and 2022 editions — always confirm which edition a document cites before trusting a control number.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },
  { term: "Statement of Applicability (SoA)", definition: "The document an ISO/IEC 27001-certified organization produces listing which Annex A controls it has selected, excluded, and implemented, and why — the artifact an auditor actually reviews rather than the standard's text itself.", category: "Compliance & Governance", chapters: ["compliance-for-iam"] },

  { term: "PAM (Privileged Access Management)", definition: "The IAM market category and discipline focused on managing the smallest, highest-risk slice of identities in an organization — privileged accounts whose compromise would cause outsized damage. Adds credential vaulting, session recording, and just-in-time privilege elevation on top of whatever workforce IAM/CIAM system already handles everyday authentication and authorization.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Privileged account", definition: "Any account whose normal operating permissions exceed what a typical end user holds — root/domain-admin accounts, database admin accounts, cloud-provider root accounts, and broadly-permissioned service accounts. Not every admin account is privileged in the PAM sense; scope and blast radius, not the word \"admin,\" determine it.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Credential vaulting", definition: "Storing privileged credentials (root passwords, database connection strings, SSH keys, API secrets) in an encrypted vault rather than having them memorized or shared directly; a human or script checks a credential out when needed instead of holding it permanently.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Session recording (PAM context)", definition: "Recording keystrokes and/or screen activity during a privileged session (e.g. an SSH session to a production database) for later audit — the PAM-specific analogue of a security camera on a vault door, capturing what happened during access, not just that access occurred.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Just-in-time (JIT) privilege elevation", definition: "Granting elevated permissions for a limited window and a specific task rather than holding them permanently; the permission is automatically revoked afterward, shrinking how long a compromised privileged credential would remain dangerous. Contrast with standing privileged access.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Standing privileged access", definition: "Elevated permissions held permanently rather than granted just-in-time for a specific task — the default a PAM program tries to reduce, since a permanently-elevated account is dangerous for as long as its credential exists, not just while it's actively being used.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Break-glass access", definition: "A deliberately logged, alarm-raising emergency path that bypasses a PAM program's normal request-approval loop when something urgent requires immediate privileged access; used rarely and audited heavily whenever it is used.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Bastion host (jump server)", definition: "A single hardened chokepoint that all privileged connections to sensitive systems must pass through, giving a PAM program one place to monitor, record, and cut off access instead of administrators connecting directly to sensitive systems from anywhere.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Total cost of ownership (TCO) in an IAM context", definition: "The full cost of running an identity system, not just its license or subscription price — including infrastructure, operational expertise, patching/tuning labor, data-residency implications, and vendor lock-in risk. The right lens for comparing a self-hosted open-source system to a commercial SaaS alternative, since \"no license fee\" is not the same claim as \"cheap overall.\"", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Open-source vs. commercial IAM", definition: "A framing axis for comparing identity products: an open-source product (like Keycloak) carries no license fee and can be inspected/modified freely, in exchange for the adopting organization owning more of the operational and expertise burden; a commercial product bundles that operational work into its price. Not the same axis as self-hosted vs. SaaS — a commercial product can still be self-hosted, and some open-source projects are offered as managed SaaS by third parties.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Self-hosted vs. SaaS/managed IAM", definition: "A framing axis for comparing identity products based on who operates the running system: self-hosted means the adopting organization runs its own infrastructure (full control, full operational responsibility); SaaS/managed means a vendor runs it (less control and less visibility into exactly how it behaves or where data lives, in exchange for outsourcing the operational burden).", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Data residency (IAM context)", definition: "Where identity data is physically stored and which jurisdiction's laws govern it — a real driver toward self-hosting an identity system for regulated organizations, independent of the pure dollar-cost TCO comparison between self-hosted and SaaS options.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Vendor lock-in (IAM context)", definition: "The cost and difficulty of leaving a given identity product later — driven by proprietary extensions, migration tooling quality, and contract terms. Rarely shows up on an invoice, but belongs in the same total-cost-of-ownership conversation as subscription price and operational burden.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Operational burden (IAM context)", definition: "The ongoing work of keeping an identity system running correctly and securely — patching, monitoring, capacity planning, clustering/failover, and maintaining the protocol expertise to configure it correctly. The main thing a self-hosted deployment takes on that a SaaS deployment largely outsources to the vendor.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Four-category IAM market taxonomy", definition: "This course's framing of the IAM market as four distinct, overlapping-but-separate categories — Workforce IAM, CIAM, PAM, and IGA — distinguished by who is managed (an organization's own people vs. external customers) and what kind of access is at stake (everyday application access vs. elevated/governance-level access). A vendor's strength in one category doesn't imply fitness for another.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Point solution vs. platform IAM", definition: "A framing distinction between a vendor/product that does one IAM job well (e.g. a dedicated PAM-only or IGA-only tool) versus a broader platform that bundles multiple categories (e.g. workforce IAM and CIAM together). Bundling convenience is a real benefit, but it doesn't guarantee best-in-category depth in every bundled piece.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Corporate ownership volatility (IAM market)", definition: "The IAM/PAM/IGA vendor landscape changes ownership and branding fast via acquisition and rebrand (e.g. ForgeRock into Ping Identity, CyberArk into Palo Alto Networks' Idira) — a reason to re-verify a vendor's current corporate status before relying on it in a real purchasing decision, rather than trusting a reference written even a year earlier.", category: "Market & vendors", chapters: ["iam-market-landscape"] },
  { term: "Privileged session", definition: "A connected, active use of a privileged account against a sensitive system (e.g. an SSH session to a production database or an RDP session to a domain controller) — the unit of work that PAM tooling specifically targets for routing through a bastion host, recording, and time-boxing via just-in-time elevation.", category: "Market & vendors", chapters: ["iam-market-landscape"] },

  { term: "Resource Owner", definition: "OAuth 2.0's name for the entity capable of granting access to a protected resource — in nearly every real scenario, the human end user. Distinct from chapter 7's IdP/SP/RP vocabulary, which never needed to name the end user as a formal role.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Client (OAuth role)", definition: "OAuth 2.0's name for the application requesting access to a protected resource on the resource owner's behalf — \"the app.\" Not identical in shape to chapter 7's SP/RP: an OAuth client requests and holds tokens to call APIs, while authenticating the end user directly is OpenID Connect's job (chapter 15), layered on top. In Keycloak, this abstract role becomes a concrete, realm-scoped client record. Two settings decide its real-world behavior: publicClient (confidential clients get an auto-generated client secret and are expected to run somewhere that secret stays hidden; public clients get none and rely on PKCE instead) and which grant-type toggles (standardFlowEnabled, directAccessGrantsEnabled, serviceAccountsEnabled) are turned on. Registering a client the wrong type (e.g. a secret on a browser SPA) is a real, exploitable mistake, not a style choice.", category: "OAuth 2.0", chapters: ["oauth2-core", "clients-and-scopes"] },
  { term: "Authorization Server", definition: "The OAuth 2.0 role that authenticates the resource owner, obtains their authorization, and issues access tokens to the client. Roughly fills chapter 7's Identity Provider (IdP) role, though the two vocabularies aren't a clean 1:1 rename. Concretely, a Keycloak realm is this role's Keycloak instantiation: a fully isolated namespace of its own users, credentials, clients, roles, groups, identity providers, and authentication flows, invisible to every other realm on the same server. One Keycloak installation can host many realms side by side, each independently playing the Authorization Server role for its own clients — chapters 13-15 used a third-party Authorization Server (Duende's public demo IdentityServer); starting chapter 20 the reader runs their own realm instead.", category: "OAuth 2.0", chapters: ["oauth2-core", "keycloak-architecture"] },
  { term: "Resource Server", definition: "The OAuth 2.0 role hosting protected resources and accepting requests bearing an access token — in plain terms, an API. Has no equivalent in chapter 7's IdP/SP/RP vocabulary, because SSO/federation never needed to name \"a protected API\" as a role.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Authorization grant", definition: "The general OAuth 2.0 term for whatever a client presents to the authorization server to prove it's entitled to a token on the resource owner's behalf — an authorization code, a set of client credentials, a device code, etc. \"Grant type\" names which specific kind is in use for a given request.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Grant type", definition: "A defined way for an OAuth 2.0 client to obtain an access token — authorization code, client credentials, device code, and the discouraged ROPC and Implicit grants among them. Full survey in chapter 13; client credentials and device code get full depth in chapter 14.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Authorization code", definition: "A short-lived, single-use value returned to the client via browser redirect after the resource owner authenticates, deliberately not powerful enough on its own to be worth stealing — it must still be exchanged at the token endpoint, server-to-server, for an actual access token.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Authorization endpoint", definition: "The OAuth 2.0 authorization server endpoint (conventionally /authorize) the client redirects the resource owner's browser to, to begin authentication and authorization — e.g. /connect/authorize on the Duende demo server used in chapter 13's lab.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Token endpoint", definition: "The OAuth 2.0 authorization server endpoint (conventionally /token) a client calls directly, server-to-server, to exchange an authorization grant (a code, client credentials, etc.) for an actual access token — never called from inside the browser redirect flow itself.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Scope (OAuth)", definition: "A client-requested, space-separated identifier naming a slice of access being asked for (e.g. openid, profile, api) — the mechanism by which an OAuth token's power is limited to only what was actually requested and granted, rather than full access to everything the resource owner could authorize. In Keycloak, this becomes a concrete client scope: a named, reusable bundle of protocol mapper configuration and role-scope mappings, attachable to any client as either a default scope (always included, no scope= parameter needed) or an optional scope (only included if explicitly requested). Defining a scope once and attaching it to many clients means a later claim change propagates everywhere at once.", category: "OAuth 2.0", chapters: ["oauth2-core", "clients-and-scopes"] },
  { term: "Consent (OAuth)", definition: "The resource owner's explicit approval of the specific scopes a client is requesting, typically shown as a screen during the authorization code flow. Some authorization servers skip it for pre-trusted first-party clients — the live lab's demo clients proceed straight from login to redirect with no separate consent screen.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Resource Owner Password Credentials (ROPC)", definition: "A legacy OAuth 2.0 grant type where the client collects the resource owner's username and password directly and trades them for a token in one request, with no redirect to the authorization server at all. Discouraged by current best practice: it trains users to type credentials into arbitrary client apps and defeats the authorization server's ability to apply its own MFA or step-up checks. Full security reasoning in chapter 18.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Implicit grant (OAuth)", definition: "A legacy OAuth 2.0 grant type that returns an access token directly in the browser's URL fragment, skipping the authorization-code exchange step. Discouraged by current best practice: a token in a URL fragment is exposed to browser history, referrer leakage, and any script able to read the current URL. Full security reasoning in chapter 18.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "PKCE (Proof Key for Code Exchange)", definition: "An OAuth 2.0 extension (RFC 7636) where the client generates a secret (code_verifier) and sends only its one-way hash (code_challenge) in the initial authorize request; the plaintext verifier is only revealed at the final token exchange, so an intercepted authorization code alone isn't enough to obtain tokens. Current best practice recommends it on every authorization code flow, not only for public clients that lack a secret.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Code verifier", definition: "PKCE's client-generated, high-entropy random string (43-128 characters per RFC 7636 §4.1), created fresh per authorization attempt and kept on the client until the final token exchange, where it's sent in plaintext so the server can verify it matches the earlier code_challenge.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Code challenge", definition: "PKCE's derived value sent in the clear in the initial authorize request: SHA-256(code_verifier), base64url-encoded with padding stripped, under the S256 method. One-way — it cannot be reversed back into the verifier, which is exactly why intercepting it in transit doesn't help an attacker.", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "code_challenge_method", definition: "The PKCE authorize-request parameter naming how code_challenge was derived from code_verifier — \"S256\" (SHA-256 hash, mandatory to implement on the server) or \"plain\" (the challenge equals the verifier itself, kept only for constrained clients that can't hash, and strictly weaker since it offers no protection if the challenge itself is intercepted).", category: "OAuth 2.0", chapters: ["oauth2-core"] },
  { term: "Open redirector (OAuth context)", definition: "The security failure RFC 6749 §3.1.2.2 names directly: an authorization endpoint that lacks a redirect-URI registration requirement can be abused as a generic open redirector, sending a user-agent anywhere an attacker specifies under the trusted authorization server's own domain.", category: "OAuth 2.0 security", chapters: ["oauth2-core"] },
  { term: "Authorization code injection", definition: "An attack where an authorization code intended for one redirect destination is captured and submitted to a different destination (often the attacker's own), exploiting loose or missing redirect_uri exact-match validation. Chapter 13 demonstrates this live and concretely against a public demo server whose redirect_uri validation was found not to enforce RFC 6749's exact-match requirement.", category: "OAuth 2.0 security", chapters: ["oauth2-core"] },

  { term: "Device code", definition: "The opaque code an authorization server issues to the constrained device itself during a device authorization request, used only in the device's own polling requests to the token endpoint — never shown to the human user.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "User code", definition: "The short, human-typeable code issued alongside a device code, displayed by the constrained device and entered by the human at the verification URI to link their browser session to that specific pending device authorization request.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Verification URI", definition: "The URL a device-flow user visits on a separate, browser-capable device to enter the user code and complete login/consent. verification_uri_complete embeds the user code as a query parameter so it can be opened directly (e.g. from a QR code) without the human retyping the code.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Device-flow polling", definition: "The repeated token-endpoint requests a device-flow client makes while waiting for the human step to finish, honoring the server-advertised interval. The authorization server responds authorization_pending until approval, slow_down if the client polls faster than instructed, and an error (or real tokens) once the code is resolved or expires.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Client credentials grant", definition: "An OAuth 2.0 grant (RFC 6749 §4.4) for pure machine-to-machine access: the client authenticates directly to the token endpoint with its own credentials and receives an access token scoped to itself, with no resource owner, browser, or user context involved at any point. Previewed in chapter 13 (confirmed live against the demo server's m2m client).", category: "OAuth grants", chapters: ["oauth2-extended", "oauth2-core"] },
  { term: "Device authorization grant", definition: "An OAuth 2.0 grant (RFC 8628) for clients that cannot receive a browser redirect at all — a CLI tool, a smart TV, an IoT device. The constrained device requests a device code and a short user code from the authorization server, displays the user code and a verification URL, and polls the token endpoint until a human completes login and approval on a separate, more capable device. Needs no registered redirect_uri. Previewed in chapter 13; this course's primary \"real human step, real round trip\" lab here in chapter 14.", category: "OAuth grants", chapters: ["oauth2-extended", "oauth2-core"] },
  { term: "Machine-to-machine (M2M) authentication", definition: "One backend system or service authenticating directly to another with no human or user context in the request at all. The client credentials grant is OAuth's standard mechanism for this.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Token revocation", definition: "Asking an authorization server to invalidate a specific, already-issued token before its natural expiry, via a dedicated revocation endpoint (RFC 7009). Whether this actually stops the token from working depends on whether the server has a server-side record of that token to delete — see self-contained access token.", category: "Tokens & Sessions", chapters: ["oauth2-extended"] },
  { term: "Revocation endpoint", definition: "The OAuth endpoint a client calls to request that a specific token be invalidated early. RFC 7009 §2.1 permits the authorization server to return success (HTTP 200) even when it cannot actually invalidate the identified token, specifically so the endpoint can't be used to probe which tokens are real.", category: "Tokens & Sessions", chapters: ["oauth2-extended"] },
  { term: "Reference token (opaque access token)", definition: "An access-token design where the token itself is a meaningless random string and the authorization server stores the actual token data server-side. Revocation is immediately effective — deleting the server-side record makes the very next introspection call correctly report the token inactive — at the cost of needing a store the server must maintain and look up on every check.", category: "Tokens & Sessions", chapters: ["oauth2-extended"] },
  { term: "Self-contained access token", definition: "An access-token design (typically a JWT) where every claim and a signature live inside the token itself, verifiable by anyone holding the signing key's public half with zero server-side lookup. Revoking one can return success without any effect, because there is no server-side record to delete — introspection against it typically re-checks only the signature and expiry, not a revocation list. A direct, concrete instance of chapter 8's revocation problem, confirmed live in this chapter's own lab.", category: "Tokens & Sessions", chapters: ["oauth2-extended"] },
  { term: "Token exchange", definition: "An OAuth 2.0 extension grant (RFC 8693, urn:ietf:params:oauth:grant-type:token-exchange) letting a client trade one security token for another — commonly to downscope a token's privilege before forwarding it downstream, or to support one service acting for another via delegation or impersonation. Covered conceptually only here, since this course's live demo server doesn't support a live lab for it.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Subject token", definition: "In a token-exchange request (RFC 8693), the token identifying the party on whose behalf, or as whom, the newly issued token is being requested.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Actor token", definition: "In a token-exchange request (RFC 8693), an optional second token identifying the immediate party making the exchange request itself, distinct from the subject the resulting token is about — present when the exchange needs to record who is actually making the call.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Impersonation (token exchange)", definition: "A token-exchange outcome (RFC 8693) where the issued token asserts the subject's identity with no act claim recording that it was exchanged on their behalf — a downstream service cannot distinguish the resulting request from one the original subject made directly.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Delegation (token exchange)", definition: "A token-exchange outcome (RFC 8693) where the issued token asserts the subject's identity but retains an act claim identifying the actor exercising it — a downstream service can see that one party is acting on behalf of another, rather than being indistinguishable from the subject's own request.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Downscoping", definition: "Using token exchange (or a similar mechanism) to trade a token for a new one with a narrower scope and/or audience than the original, so a token forwarded to a less-trusted downstream service carries only the minimum privilege it actually needs.", category: "OAuth grants", chapters: ["oauth2-extended"] },
  { term: "Active (introspection claim)", definition: "The boolean field at the center of an RFC 7662 introspection response: true if the authorization server currently considers the token valid, false otherwise (including for tokens it has never heard of, which get back almost no other information deliberately).", category: "Tokens & Sessions", chapters: ["oauth2-extended"] },

  { term: "OpenID Connect (OIDC)", definition: "An identity layer built on top of OAuth 2.0, adding a standardized ID token, a discovery document, and a UserInfo endpoint so a client can learn who authenticated, not just get authorization to call an API. Reuses OAuth's grants (authorization code, device, etc.) unchanged.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "Discovery document", definition: "A single, well-known JSON document (fetched from /.well-known/openid-configuration, appended to an issuer URL) that an OIDC provider publishes describing its own endpoints and capabilities, so a client can learn them without hardcoding. The concrete, standardized implementation of chapter 7's general metadata/trust concept.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "ID token", definition: "A JWT issued alongside the usual OAuth tokens when a request includes the openid scope, carrying claims about who authenticated and when. Proves authentication, not authorization — its audience (aud) claim names the client itself, never a resource server, so it should never be sent to an API in place of an access token.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "UserInfo endpoint", definition: "An OIDC endpoint, named in the discovery document, that returns the same kind of standard claims as an ID token when called live with a valid access token issued with at least the openid scope. Useful when claims might have changed since login or when only an access token (not an ID token) is available.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "openid scope", definition: "The OIDC scope that makes a request an identity request rather than plain OAuth — including it is what tells the authorization server to also issue an ID token. Required for OIDC; without it, no ID token is issued and UserInfo access is not granted.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "profile scope", definition: "A standard OIDC scope that unlocks a bundle of standard profile claims (name, given_name, family_name, preferred_username, picture, locale, and others) on the ID token and/or UserInfo response, if requested.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "email scope", definition: "A standard OIDC scope that unlocks the email and email_verified claims on the ID token and/or UserInfo response, if requested.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "Standard claim (OIDC)", definition: "A claim OIDC Core itself defines and names (e.g. sub, name, email, email_verified), as opposed to a custom claim a specific provider adds on top. Standard claims are organized into scope bundles (profile, email) so a client requests one scope rather than naming claims individually.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "Custom claim", definition: "A claim beyond OIDC's standard set that a provider defines and advertises itself (e.g. a tenant_id or subscription-tier claim) — not something a client can request into existence by trying arbitrary scope names. In Keycloak, configured via a client scope's protocol mapper. Concretely demonstrated in chapter 24: a Keycloak client scope's protocol mapper (type oidc-usermodel-attribute-mapper) reading a real user attribute (department) and writing it under a chosen claim name into the ID token, access token, and/or UserInfo response via three independent boolean flags (id.token.claim, access.token.claim, userinfo.token.claim). Verified live: a real token minted for a real user carried \"department\": \"Engineering\" in both the ID token and access token, and the same value came back from a live UserInfo call.", category: "OpenID Connect", chapters: ["openid-connect", "clients-and-scopes"] },
  { term: "claims_supported", definition: "A field in the OIDC discovery document listing every claim a provider is willing to return, across all of its supported scopes — an advertised ceiling. A claim missing from this list can never be produced by any scope combination; getting it requires the provider to add and advertise a custom claim.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "scopes_supported", definition: "A field in the OIDC discovery document listing every scope a provider accepts, standard and provider-specific. Requesting a scope not in this list is simply not honored, not silently granted.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "sub (subject claim)", definition: "The ID token/UserInfo claim carrying a stable, provider-assigned identifier for the authenticated principal — the OIDC-specific instance of chapter 2's general Subject concept, concretely realized as one JSON field every ID token must carry.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "email_verified claim", definition: "A standard OIDC claim distinguishing 'this email address was confirmed through a verification flow' from merely 'a user typed this into a form.' Conflating a successful login with a verified email is a real, consequential application bug this claim exists specifically to prevent.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "nonce (OIDC)", definition: "A random value a client optionally sends in the authorization request and the provider echoes back unchanged inside the ID token, letting the client verify this specific ID token was issued in response to this specific request it made — a defense against replay and mix-up attacks, covered in full in chapter 18.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "auth_time claim", definition: "An ID token claim recording when the user actually authenticated, distinct from iat (when this particular token was issued) — the distinction matters once refresh tokens can mint a new ID token well after the original login event.", category: "OpenID Connect", chapters: ["openid-connect"] },
  { term: "jwks_uri", definition: "A discovery-document field naming where a client fetches the provider's current public key set to verify an ID token's signature, looked up by kid rather than hardcoded. Full signature-verification mechanics are chapter 16's subject; this chapter only establishes that the URL itself comes from discovery, not a hardcoded value.", category: "OpenID Connect", chapters: ["openid-connect"] },

  { term: "JWS (JSON Web Signature)", definition: "A JSON-based format (RFC 7515) for cryptographically signing a payload so a recipient can verify who signed it and that it hasn't been altered, without hiding the payload's contents — anyone who has the token can still read it. Most access and ID tokens issued by OAuth/OIDC providers, including every token this course has decoded so far, are JWS, not JWE.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWE (JSON Web Encryption)", definition: "A JSON-based format (RFC 7516) for encrypting a payload so only a holder of the right decryption key can read its contents. Far less common in everyday OAuth/OIDC deployments than JWS — most access and ID tokens are signed, not encrypted — but used when a token's claims themselves need to stay confidential from anyone but the intended recipient.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWK (JSON Web Key)", definition: "A single cryptographic key represented as a JSON object (RFC 7517), carrying its key type (kty), intended use, algorithm, key id (kid), and the key material itself (e.g. an RSA public key's modulus n and exponent e). A verifier fetches JWKs, not raw key files, to check a JWS signature.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWKS (JSON Web Key Set)", definition: "A JSON document (RFC 7517 §5) containing an array of JWKs — typically every signing key an issuer currently considers valid, past and present, until retired. A verifier fetches the JWKS endpoint (often published in the discovery document's jwks_uri field, chapter 15) to get the current public keys needed to verify a JWS signature, without the issuer ever sharing a private key.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "kid (Key ID)", definition: "A header parameter inside a JWT identifying which specific key, out of possibly several in a JWKS response, was used to sign it. A verifier reads the token's kid, finds the JWK in the JWKS response whose own kid matches, and uses that key to check the signature — the mechanism that makes key rotation possible without immediately breaking every already-issued token.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWT header", definition: "The first of a JWT's three base64url-encoded, dot-separated segments. A small JSON object declaring at minimum the signing algorithm (alg) and typically the key id (kid) the verifier should use, plus a token type (typ). Readable by anyone — it is not encrypted.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWT payload", definition: "The second of a JWT's three base64url-encoded segments: the JSON object holding the token's claims (subject, issuer, audience, expiry, and so on — chapter 8). Base64url is an encoding, not encryption, so the payload is readable by anyone who has the token, a very common and consequential beginner misconception to correct early.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "JWT signature", definition: "The third of a JWT's three base64url-encoded segments: the cryptographic signature computed over the header and payload segments (the signing input), proving the token wasn't altered after signing and, for asymmetric algorithms, which private key signed it. It does not hide the header or payload's contents.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "base64url encoding", definition: "A URL- and filename-safe variant of base64 encoding (RFC 4648 §5) that swaps +/ for -/_ and drops padding, used to pack each JWT segment's raw bytes into text that survives being placed in a URL or HTTP header. It is reversible by anyone with no key or secret required — encoding is not encryption.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Compact serialization", definition: "The dot-separated, three-segment text form (header.payload.signature) that JWS most commonly uses on the wire — the format this course calls simply 'a JWT.' JWS also defines a more verbose JSON serialization for cases needing multiple signatures, rarely seen in everyday OAuth/OIDC use.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "alg (algorithm) header parameter", definition: "The JWT header field naming the cryptographic algorithm used to sign (or encrypt) the token, e.g. HS256 or RS256. A verifier that blindly trusts this field's value from an untrusted token, rather than enforcing an algorithm it already expects, opens the door to algorithm confusion attacks.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Algorithm confusion (alg validation)", definition: "A real, named JWT security flaw where a verifier accepts whatever algorithm a token's own alg header claims rather than enforcing an algorithm the verifier expects, letting an attacker craft a forged token using a weaker or inappropriate scheme the issuer never intended for that key (for example, tricking an RS256 verifier into treating a public key as an HMAC secret). Full defenses are chapter 18's subject; this chapter names the problem so it isn't a surprise there.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Symmetric signing (HS256)", definition: "Signing a JWT with a single shared secret key, used both to sign and to verify (HMAC-SHA256, hence HS256). Fast and simple, but every party that needs to verify a token must hold the same secret a signer uses to create one — exposing that secret anywhere lets the holder forge tokens, not just read them.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Asymmetric signing (RS256 / ES256)", definition: "Signing a JWT with a private key that only the issuer holds, verifiable by anyone holding the corresponding public key (RS256 uses RSA, ES256 uses elliptic-curve cryptography). This is why an issuer can safely publish its verification keys in a public JWKS endpoint: the public key only lets you check a signature, never forge one, unlike a symmetric secret.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Signing input", definition: "The exact bytes a JWS signature is computed over: the base64url-encoded header, a literal dot, and the base64url-encoded payload — nothing else. A verifier must reconstruct this same signing input from the token it received and check the signature against it, which is also why altering even one character of the header or payload invalidates the signature.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Key overlap period", definition: "The deliberate window during signing-key rotation where a JWKS response lists both the outgoing and incoming signing keys at once: new tokens are already signed with the new key, while tokens signed earlier with the old key remain verifiable because the old key is still present in JWKS. Ending the overlap too early — removing the old key before every token it signed has expired — breaks verification for still-valid tokens.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },
  { term: "Digital signature", definition: "A cryptographic value computed over a message with a private (or shared secret) key, letting anyone with the matching verification key confirm both that the message hasn't been altered and, for asymmetric schemes, which key produced it — the general cryptographic primitive a JWS token applies to its header and payload.", category: "JWT & Cryptography", chapters: ["jwt-and-crypto"] },

  { term: "NameID", definition: "The element inside a SAML assertion's Subject that identifies the user to the SP, in a declared format (e.g. email address, or an opaque persistent identifier). Not always human-readable or reusable as an email — an SP should key its local account mapping on whatever format the IdP actually declares, not assume a specific one.", category: "Protocols", chapters: ["saml2"] },
  { term: "SubjectConfirmation", definition: "The part of a SAML assertion's Subject that ties the assertion to the specific browser exchange it was issued for (typically the bearer confirmation method, with a recipient URL and expiry), making it harder for a captured assertion to be replayed in an unrelated context.", category: "Protocols", chapters: ["saml2"] },
  { term: "AuthnRequest", definition: "The SAML protocol message an SP sends to an IdP to begin SP-initiated SSO, asking the IdP to authenticate the user and return an assertion. Small enough to be carried over the HTTP-Redirect binding as a URL parameter.", category: "Protocols", chapters: ["saml2"] },
  { term: "AuthnStatement", definition: "The part of a SAML assertion recording that authentication actually happened: when (AuthnInstant) and by what method (AuthnContextClassRef, e.g. password vs. a stronger multi-factor context).", category: "Protocols", chapters: ["saml2"] },
  { term: "AttributeStatement", definition: "The optional part of a SAML assertion carrying arbitrary name/value attributes about the user (department, role, email) that the IdP is willing to hand to this specific SP — where most of the useful payload in a SAML login lives in practice.", category: "Protocols", chapters: ["saml2"] },
  { term: "Conditions (SAML)", definition: "The part of a SAML assertion an SP must check before trusting it: a NotBefore/NotOnOrAfter validity window, plus an AudienceRestriction naming exactly which SP the assertion was issued for.", category: "Protocols", chapters: ["saml2"] },
  { term: "AudienceRestriction", definition: "A constraint inside a SAML assertion's Conditions naming exactly which SP (by entityID) is permitted to accept the assertion, preventing an assertion issued for one SP from being replayed and accepted by a different one.", category: "Protocols", chapters: ["saml2"] },
  { term: "EntityDescriptor", definition: "The root XML element of a SAML metadata document, describing one entity (an IdP or an SP) — its entityID, its certificates, and its supported endpoints/bindings — exchanged so each side can configure itself correctly against the other.", category: "Protocols", chapters: ["saml2"] },
  { term: "AssertionConsumerService (ACS)", definition: "The URL on an SP where an IdP posts a SAML assertion response, declared in the SP's metadata. The SAML equivalent of a registered redirect URI, specific to where assertions (not authorization codes) land.", category: "Protocols", chapters: ["saml2"] },
  { term: "HTTP-POST binding (SAML)", definition: "A SAML transport binding that delivers a message via an auto-submitting HTML form POST, with no practical size ceiling — the near-universal choice for carrying a signed assertion response back to the SP, since assertions routinely exceed what a URL can hold.", category: "Protocols", chapters: ["saml2"] },
  { term: "HTTP-Redirect binding (SAML)", definition: "A SAML transport binding that delivers a deflate-compressed, URL-encoded message as a query parameter on a browser redirect. Limited by practical browser URL-length ceilings, so it's typically used only for small messages like the initial AuthnRequest.", category: "Protocols", chapters: ["saml2"] },
  { term: "SP-initiated SSO", definition: "A SAML login that begins at the Service Provider: the user visits the SP first, the SP builds and sends an AuthnRequest to the IdP, and the IdP's eventual Response can be correlated back to that specific request.", category: "Protocols", chapters: ["saml2"] },
  { term: "IdP-initiated SSO", definition: "A SAML login that begins at the Identity Provider (e.g. an app-launcher portal): the user clicks a link for a specific SP with no preceding AuthnRequest, and the IdP sends an unsolicited Response directly to the SP's ACS. Harder to defend against replay than SP-initiated SSO, since there's no request to correlate against — the SP leans more heavily on Conditions validation instead.", category: "Protocols", chapters: ["saml2"] },
  { term: "XML digital signature (XML-DSig)", definition: "The signature mechanism wrapping a SAML assertion (or metadata document), letting the relying party cryptographically verify the content came from the claimed issuer and wasn't tampered with. Requires canonicalizing the XML before verifying, which is notoriously fiddlier to implement correctly than JWS (chapter 16) — a real factor in SAML's historically higher integration cost.", category: "Protocols", chapters: ["saml2"] },
  { term: "RelayState", definition: "An opaque value an SP attaches to a SAML request (or an IdP echoes back with a response) to preserve application state across the redirect/POST round trip — e.g. which page the user was trying to reach — so the SP can send them to the right place after login completes.", category: "Protocols", chapters: ["saml2"] },
  { term: "XML signature wrapping attack", definition: "A class of attack against careless SAML implementations where an attacker restructures a signed assertion's XML (e.g. duplicating or relocating elements) so that the part the application reads differs from the part the signature actually covers, causing a tampered assertion to pass signature validation. A key reason mature, well-audited SAML libraries — not hand-rolled XML parsing — are the only safe way to consume SAML in production.", category: "Protocols", chapters: ["saml2"] },
  { term: "AuthnContextClassRef", definition: "The field inside a SAML assertion's AuthnStatement declaring which authentication method or context class was used (e.g. password-protected transport vs. a stronger multi-factor context) — the SAML analog of OIDC's acr claim.", category: "Protocols", chapters: ["saml2"] },

  { term: "Mix-up attack", definition: "An attack against a client configured to trust more than one authorization server, where the attacker gets the client confused about which authorization server actually issued a given authorization response — potentially causing the client to send a real authorization code or credential to the wrong (attacker-controlled) server. RFC 9700 treats defending against it as required, not optional, for any client with more than one trusted AS.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "iss validation", definition: "The mix-up-attack defense where an authorization server includes an iss parameter (RFC 9207) stating its own issuer identity in every authorization response, and the client compares that value against the issuer it expected before proceeding — aborting the flow on any mismatch. RFC 9700's preferred defense against mix-up attacks.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "State parameter (CSRF defense)", definition: "A random, unguessable value a client generates before redirecting to an authorization server, binds to the specific browser session initiating the request, and requires the callback to echo back unchanged — defeating a forged callback from a different flow (e.g. one an attacker started) because that callback would carry a different, unbound state value. The security property comes from the session binding, not merely from the value surviving the round trip. Used mechanically throughout chapter 13's lab; this is the security rationale and failure modes.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security", "oauth2-core"] },
  { term: "PKCE-everywhere", definition: "The current RFC 9700 guidance (§2.1.1) that PKCE should be used by confidential clients too, not only public clients — because PKCE protects the authorization code in flight, a layer a client secret never covers (the secret only matters at the later token-endpoint exchange). Distinct from chapter 13's PKCE mechanics (the code_verifier/code_challenge handshake itself) — this is the policy point about which clients should use it.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Token storage", definition: "The design decision of where a browser-based OAuth/OIDC client keeps the tokens it's issued — JavaScript-accessible storage (localStorage/sessionStorage), an httpOnly cookie, or (per RFC 10017) a server-side component that never exposes the token to the browser at all. Each option trades one exposure category (XSS readability vs. CSRF) for another; none is risk-free.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "httpOnly cookie", definition: "A cookie attribute that makes the cookie's value invisible to JavaScript (document.cookie never returns it) — only the browser attaches it to outgoing requests and only the server reads it. Closes the XSS-reads-the-token exposure that localStorage/sessionStorage have, but doesn't remove CSRF exposure, since the browser still attaches the cookie automatically to requests.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Authorization code interception attack", definition: "An attack where an authorization code is captured in transit — via a leaked referrer header, a malicious app sharing a native client's custom redirect URI scheme, or a misconfigured proxy/log — before it reaches the token endpoint. PKCE defeats it regardless of whether the client is public or confidential, since the attacker lacks the original code_verifier needed to redeem the stolen code.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "OAuth 2.0 Security Best Current Practice (RFC 9700 / BCP 240)", definition: "A published, final IETF Best Current Practice (January 2025) consolidating OAuth 2.0 threat-model advice previously spread across RFC 6749, RFC 6750, and the now-superseded RFC 6819 — the normative source for this chapter's PKCE-everywhere, mix-up, and CSRF guidance.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Backend-for-Frontend (BFF) pattern", definition: "A server-side component, specific to a browser-based application's own backend, that holds OAuth/OIDC tokens itself and gives the browser only an httpOnly, Secure, SameSite session cookie — so tokens never reach browser-readable storage or browser-visible JavaScript at all. RFC 10017 calls this pattern \"strongly recommended for business applications\" because it removes the token-in-the-browser exposure as a category rather than merely hardening where the token sits.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Token-mediating backend", definition: "A lighter-weight variant of the BFF pattern (RFC 10017) where a backend component still exchanges codes for tokens and sets a cookie, but the browser-based application may still receive and use some tokens directly — less isolating than a full BFF, which RFC 10017 recommends evaluating as the stronger alternative where feasible.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "SameSite cookie attribute", definition: "A cookie attribute controlling whether the browser attaches the cookie to cross-site requests. Used alongside httpOnly to reduce (not eliminate) the CSRF exposure that a cookie-based session or BFF pattern reintroduces once a token is moved out of JavaScript-readable storage.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "CSRF token", definition: "A random, single-use value generated by a client and checked on return to confirm a request genuinely originated from the session that's claimed — the generic security pattern that the OAuth state parameter is one specific application of.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Sender-constrained token", definition: "A token bound to proof that the presenter is the same party it was issued to (e.g. via a key the client holds), rather than a plain bearer token usable by whoever has it. RFC 9700 names sender-constraining as a further hardening step beyond storage/lifetime controls; full mechanics are a forward pointer to Keycloak's client/token configuration (chapters 24-25), not built out in this concept chapter.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Issuer identification (RFC 9207)", definition: "The IETF Proposed Standard (March 2022) defining the iss authorization-response parameter an authorization server uses to state its own identity, giving a client certainty about which server a response actually came from — the mechanism iss validation relies on, and RFC 9700's preferred mix-up-attack defense.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Browser-based application (OAuth security context)", definition: "An OAuth/OIDC client running as JavaScript inside a user's browser (an SPA or similar) — the specific client category RFC 10017 (\"OAuth 2.0 for Browser-Based Applications\") targets, because it's the category most exposed to XSS-driven token theft and the one with the most storage-location trade-offs to choose between.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },
  { term: "Cross-Site Request Forgery (CSRF) via authorization callback", definition: "A CSRF attack specifically against the OAuth/OIDC redirect handshake: an attacker starts their own legitimate authorization flow and tricks a victim's browser into completing that callback instead of one the victim initiated, potentially linking the victim's session to the attacker's identity. The state parameter is the standard defense.", category: "OAuth/OIDC Security", chapters: ["oauth-oidc-security"] },

  { term: "Quarkus distribution", definition: "The Java framework Keycloak's server is built on, chosen for fast startup and a small memory footprint in containerized environments — the opposite design goal from the older general-purpose Java EE application servers Keycloak originally shipped on. Became Keycloak's fully-supported default starting with Keycloak 17 (December 2021), replacing an earlier WildFly-based distribution that was phased out over the following releases (sources differ slightly on the exact final-removal version).", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Build-time configuration (Keycloak)", definition: "Keycloak settings baked into the server image when running kc build — e.g. which database vendor, whether clustering is enabled, which features are turned on. Changing one requires re-running kc build to re-optimize the server; this is the deliberate, slower half of Keycloak's configuration split, contrasted with runtime configuration.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Runtime configuration (Keycloak)", definition: "Keycloak settings read fresh every time the server starts, via kc start/kc start-dev, environment variables, or conf/keycloak.conf — e.g. the database connection URL/credentials, hostname, HTTP(S) port, log level. Changing one only needs a restart, not a rebuild, unlike build-time configuration.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "kc build / kc start", definition: "The two-stage Quarkus-distribution workflow: kc build produces an optimized server image from build-time configuration choices, and kc start (or kc start-dev for development) launches that image with runtime configuration supplied fresh at startup.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Database backend (Keycloak)", definition: "The relational database Keycloak persists realms, users, credentials, clients, and (depending on deployment mode) sessions to — it is not a database-free product. Officially supported vendors as of Keycloak 26.x are PostgreSQL (plus EnterpriseDB Advanced and Amazon Aurora PostgreSQL), MariaDB, MySQL, Microsoft SQL Server (plus Azure SQL variants), and Oracle Database; dev-file/dev-mem exist but are development-only and explicitly deprecated as a production default.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Standalone deployment", definition: "Running Keycloak as a single kc process directly on a VM or bare host, talking to a nearby database with no container or orchestration layer involved — the simplest point on Keycloak's deployment spectrum, suited to small internal tools or quick evaluation.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Containerized deployment", definition: "Running Keycloak and its database each as a container, typically wired together with Docker Compose — the middle point on Keycloak's deployment spectrum, and the shape this course's own lab environment uses starting chapter 20 (Keycloak 26.8.2 + PostgreSQL 17).", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Kubernetes deployment (Keycloak)", definition: "Running Keycloak as one or more pods managed by the Keycloak Operator or a Helm chart, letting Kubernetes handle scheduling, restarts, and elastic scaling of nodes — the far end of Keycloak's deployment spectrum, suited to organizations needing elastic scale and already operating Kubernetes. Full depth in chapter 42.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Infinispan", definition: "The distributed, in-memory data grid Keycloak embeds as its caching layer for clustering, configured by default via conf/cache-ispn.xml. Multiple Keycloak nodes share session and authentication-session state through Infinispan so a request can land on any node in the cluster and still see consistent data. Still Keycloak's current clustering technology as of 26.x. Full configuration in chapter 41.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Clustering (Keycloak)", definition: "Running multiple Keycloak nodes that share session and authentication-session state (via embedded Infinispan) behind a load balancer, so throughput scales beyond one node and no single node is a point of failure within one site. Distinct from multi-site high availability, which addresses resilience across data centers/regions rather than throughput/failover within one.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "High availability (Keycloak context)", definition: "Keycloak's resilience strategy against node or site failure, ranging from single-cluster deployments (embedded Infinispan, no external dependency) to multi-site architectures spanning multiple data centers/regions. Previewed here; full depth and hands-on configuration in chapter 41.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Multi-site (multi-cluster) deployment", definition: "A Keycloak high-availability architecture spanning more than one data center or region, distinct from single-site clustering. Keycloak's own documentation describes more than one approach: an older one requiring a separate external Infinispan cluster per site, and a newer one that relies on the shared database to carry session state across sites instead — each trading a different kind of operational cost. Full depth in chapter 41.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Load balancer (Keycloak context)", definition: "The component that distributes incoming requests across multiple Keycloak nodes in a cluster or multi-site deployment. Required for any multi-node Keycloak architecture; often included automatically by a Kubernetes platform but a separate, explicit dependency in standalone or Docker Compose clustering setups.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },
  { term: "Realm (Keycloak)", definition: "A fully isolated management namespace within one Keycloak server — its own users, credentials, clients, roles, groups, identity providers, and authentication flows, invisible to and unreachable from every other realm on the same server. Concretely implements chapter 13's OAuth 2.0 Authorization Server role. Keycloak ships with a built-in master realm reserved for administering Keycloak itself; this course creates a separate northwind-apps realm starting chapter 20 rather than mixing application use into master.", category: "Keycloak Architecture", chapters: ["keycloak-architecture"] },

  { term: "Bootstrap admin", definition: "The administrator account Keycloak creates automatically the very first time it starts, from KC_BOOTSTRAP_ADMIN_USERNAME/KC_BOOTSTRAP_ADMIN_PASSWORD (or an auto-generated temp-admin/password if omitted). It exists solely to get an administrator logged in before any other admin account exists, and is created only once — only when the master realm doesn't yet exist. See Temporary admin user for what 'temporary' means here.", category: "Keycloak Core", chapters: ["keycloak-architecture", "installing-keycloak"] },
  { term: "Temporary admin user", definition: "The label Keycloak itself applies to a bootstrap admin account: fully functional (it can log into the Admin Console, the Admin REST API, or kcadm.sh with full privileges) but meant to be removed manually once a real, named administrator account exists. 'Temporary' describes how long it should be kept, not a technical restriction on what it can do.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "start-dev mode", definition: "Keycloak's development startup command. Relative to production mode it disables strict hostname checking, enables plain HTTP without requiring TLS, uses local-only (non-distributed) caching, disables theme/template caching, and starts with no further configuration at all — convenient for a local lab, unsafe for anything reachable outside one developer's own machine. This course's lab stack runs it via docker-compose's command: start-dev.", category: "Keycloak Core", chapters: ["keycloak-architecture", "installing-keycloak"] },
  { term: "Production mode (Keycloak)", definition: "Keycloak's start command (as opposed to start-dev): requires explicit hostname configuration, disables plain HTTP and expects HTTPS/TLS to be configured, supports distributed/clustered caching, and refuses to start at all without that configuration present — Keycloak's own docs call this 'secure by default'. Full production checklist in chapter 45.", category: "Keycloak Core", chapters: ["keycloak-architecture", "installing-keycloak"] },
  { term: "kcadm.sh", definition: "Keycloak's bundled command-line client for the Admin REST API, shipped at /opt/keycloak/bin/kcadm.sh in the official image. Used throughout chapters 20-26 as the scriptable, verifiable way to confirm an Admin Console step actually worked; full depth (scripting, batch operations, automation patterns) is chapter 27's subject.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Realm creation (kcadm.sh / Admin Console)", definition: "The practical act of creating a new Keycloak realm, either via the Admin Console's 'Create realm' button plus a name field, or scriptably via kcadm.sh create realms -s realm=<name> -s enabled=true against the Admin REST API. The two are mechanically equivalent — the Console is a thin UI layer over the same API kcadm.sh calls directly. A newly created realm has a key pair and self-signed certificate generated automatically.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Health endpoint (Keycloak)", definition: "Keycloak's built-in liveness/readiness checks, enabled via KC_HEALTH_ENABLED=true and served on the management port (9000 by default) rather than the main HTTP port. /health/started covers initial startup, /health/live whether the instance should be restarted, /health/ready whether it can serve traffic, and /health aggregates all three — each returns 200 (healthy) or 503 with a JSON status body. The Keycloak container image itself lacks curl/wget, a documented fact this course's own lab run independently reproduced.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Management interface (Keycloak)", definition: "A separate port (9000 by default, set via KC_HEALTH_ENABLED and related options) Keycloak serves operational endpoints like health checks and metrics on, distinct from the main port (8080/8443) that serves the Admin Console, Admin REST API, and realm/user-facing endpoints — intended to be reachable only internally, not exposed the way the main port is.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Secure by default (Keycloak)", definition: "Keycloak's own stated design principle that its production start command deliberately refuses to run without explicit configuration (hostname, TLS, etc.) rather than silently falling back to insecure defaults — the opposite philosophy from start-dev, which is designed to run with zero configuration specifically for local development convenience.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "bootstrap-admin command", definition: "A separate kc.sh/kc.bat subcommand (bootstrap-admin user or bootstrap-admin service) for recovering admin access after the fact — distinct from the KC_BOOTSTRAP_ADMIN_* environment variables used only on first start. Can be run even before Keycloak's first-ever start, but requires every node in a cluster to be stopped first, and running it causes any pending first-start bootstrap environment variables to be ignored.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Strict hostname resolution", definition: "Keycloak's production-mode requirement that the hostname used to build links (password reset emails, redirect validation, issuer URLs) is explicitly configured rather than inferred from an incoming request's Host header. start-dev disables this, which is one of the specific reasons it's unsafe outside a local lab — an attacker-controlled Host header can otherwise influence URLs Keycloak generates.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Current realm (Admin Console)", definition: "The realm selector shown in the top-left of Keycloak's Admin Console, naming which realm the console is currently managing (master by default on a fresh instance) and letting an administrator switch to or create another realm from its dropdown, per Keycloak's official Server Administration Guide.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "docker-compose.yml (Keycloak lab stack)", definition: "This course's own two-service Docker Compose file (labs/docker/docker-compose.yml) defining a Keycloak 26.8.2 container and a PostgreSQL 17 container, with Keycloak's startup gated on Postgres's healthcheck via depends_on: condition: service_healthy. Reused, fresh (docker compose up then down -v), by every Part IV chapter's hands-on lab.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "KC-SERVICES0077", definition: "The Keycloak log-message code printed exactly once, on an instance's first-ever start, reading 'Created temporary admin user with username <name>' — the concrete, grep-able evidence that the bootstrap admin creation path actually ran.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Quarkus distribution (boot timing)", definition: "Keycloak 26's Quarkus-based runtime reports its own internal startup time in its boot log (e.g. 'started in 19.441s') separately from how long a container takes to become reachable from outside — the latter also includes container-runtime overhead and the TCP listener coming up, which is why polling a real endpoint rather than sleeping a fixed duration is the correct way to detect readiness.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Master realm application-boundary rule", definition: "The operational rule that the master realm (created automatically on first start, used only to create/manage other realms and hold Keycloak's own administrative accounts) must never host an organization's actual application users, roles, or OAuth/OIDC clients — doing so places ordinary application-level risk one hop away from instance-wide administrative control. This course's own realm plan (chapters 20-26) deliberately creates and uses northwind-apps instead.", category: "Keycloak Core", chapters: ["installing-keycloak"] },
  { term: "Readiness polling (vs. fixed sleep)", definition: "Confirming a service is actually ready by repeatedly checking a real endpoint until it answers successfully, instead of sleeping a fixed, guessed duration and assuming readiness. This chapter's lab needed 10 polling attempts (about 30 seconds) before Keycloak's discovery endpoint returned 200, demonstrating why a fixed-sleep assumption is fragile.", category: "DevOps / Lab practice", chapters: ["installing-keycloak"] },
  { term: "northwind-apps realm", definition: "The Keycloak realm created in chapter 20 (kcadm.sh create realms -s realm=northwind-apps -s enabled=true) as the shared running example for chapters 20-26: realm settings and branding (ch21), users jane.doe and priya.patel (ch22), roles/groups including the Mover-event payoff from chapter 10 (ch23), clients and protocol mappers (ch24), custom auth flows (ch25), and theming (ch26).", category: "Keycloak Core", chapters: ["installing-keycloak"] },

  { term: "Realm Settings (General tab)", definition: "The first Realm Settings tab in Keycloak's Admin Console, carrying a realm's Display Name (a human-readable label shown on login/branding surfaces instead of the internal realm id), Frontend URL (the base URL Keycloak uses to generate links back to itself, useful behind a reverse proxy), and Require SSL (External requests / None / All requests — External requests, the default, requires SSL except from private/loopback addresses).", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Require SSL (realm setting)", definition: "A General-tab realm setting with three modes, per Keycloak's official documentation: External requests (SSL required except from private IP addresses like localhost, the default), None (no SSL required — development only), and All requests (SSL required everywhere, no exceptions).", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Login tab (Realm Settings)", definition: "The Realm Settings tab controlling login-page self-service behavior: User registration, Forgot password, Remember Me, Verify email, Login with email, and Duplicate emails allowed — each a toggle on what the login screen offers, not on authentication mechanics themselves.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Forgot password (realm setting)", definition: "A Login-tab toggle that adds a \"Forgot Password?\" link to the login page. Requires realm or server SMTP settings (host and From address) to be configured, or reset emails never send. By default, federated users must log in again after a reset while internal database users on the same browser session stay logged in.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Remember Me (realm setting)", definition: "A Login-tab toggle that adds a checkbox keeping a user's session alive after the browser closes. Disabling it does not immediately invalidate sessions already created with the checkbox selected — invalidation happens lazily, the next time that session's cookie/token is used or during a background process.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "SSO Session Idle", definition: "A realm-level Tokens/Sessions setting: if a user is inactive longer than this timeout, their SSO session is invalidated. The concrete Keycloak field implementing chapter 7's generic SSO-session concept's inactivity half. Northwind Apps set this to 3,600 seconds (1 hour) in chapter 21, up from Keycloak's 1,800-second default, to tolerate meeting-length interruptions.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "SSO Session Max", definition: "A realm-level Tokens/Sessions setting: the absolute maximum time before a user's SSO session expires, regardless of continued activity. Independent of SSO Session Idle — a session that keeps getting used can still be forced to end once this ceiling is reached. Northwind Apps tightened this to 28,800 seconds (8 hours, one working day) in chapter 21, down from the 36,000-second default, specifically because it had just lengthened its idle timeout.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "SSO Session Idle/Max Remember Me", definition: "A separate pair of idle/max timeout values that apply only to sessions created with the Remember Me checkbox selected at login, distinct from the realm's regular SSO Session Idle/Max fields — enabling Remember Me does not by itself change how long a non-Remember-Me session lasts.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Client Session Idle/Max", definition: "Realm-level timeouts scoped to a specific client's own session rather than the overall SSO session: Client Session Idle is that client session's inactivity timeout, and Client Session Max is the maximum time for the client session before its refresh token expires and invalidates.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Offline Session Idle / Offline Session Max Limited", definition: "Realm settings governing offline tokens (issued with the offline_access scope for long-lived, refresh-without-re-login access): Offline Session Idle is how long an offline session may sit idle before its token is revoked; Offline Session Max Limited is a flag controlling whether a separate absolute ceiling applies at all, or whether the offline session only ever expires via idle timeout.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Access Token Lifespan", definition: "A realm-level Tokens setting controlling how long an OIDC access token Keycloak issues remains valid. Independent of SSO Session Idle/Max — a single SSO session commonly outlives many access-token mint-expire-refresh cycles. Northwind Apps raised this to 600 seconds (10 minutes) in chapter 21, up from Keycloak's 300-second default, to halve refresh round-trips while keeping a stolen token's useful window short. Concretely implements chapter 8's token-lifetime trade-off.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Access Token Lifespan For Implicit Flow", definition: "A separate, dedicated token-lifetime setting for access tokens issued via the OAuth 2.0 Implicit Flow, which issues no refresh token and so cannot rely on the regular refresh-driven access-token lifecycle.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Revoke Refresh Token", definition: "A realm-level Tokens setting: when enabled, Keycloak revokes a presented refresh token and issues a new one the client must switch to, rather than letting the same refresh token be reused indefinitely across its lifespan — a defense against a leaked refresh token being replayed after the legitimate client has already rotated past it.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Security Defenses tab (Realm Settings)", definition: "The Realm Settings tab hosting security headers (e.g. X-Frame-Options, Content-Security-Policy) and brute-force detection configuration. Previewed in chapter 21 without being configured; full depth, including the specific lockout fields, is chapter 30's subject.", category: "Keycloak Core", chapters: ["realms"] },
  { term: "Themes tab (Realm Settings)", definition: "The Realm Settings tab selecting which theme renders each of four surfaces — Login (username/password entry, OTP entry, registration, and similar login-adjacent screens), Account (the console end users manage their own account through), Admin console, and Email — plus a related Localization tab for enabling internationalization and choosing supported languages. Previewed in chapter 21 at Keycloak's built-in defaults; full branding/localization depth is chapter 26's subject.", category: "Keycloak Core", chapters: ["realms"] },

  { term: "User representation (Keycloak)", definition: "The JSON object the Admin REST API (and kcadm.sh, which wraps it) uses to read and write a user — fields like username, email, firstName, lastName, enabled, attributes, requiredActions, and a server-generated id. Every kcadm.sh user command in this chapter is a thin CLI wrapper over GET/POST/PUT requests against this representation.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Required action", definition: "Per Keycloak's own Server Administration Guide, \"actions that a user must perform at the first login\" — running after a correct credential check but before login is allowed to complete. Some are assigned deliberately by an admin (e.g. chapter 22's CONFIGURE_TOTP on priya.patel); others Keycloak adds automatically (e.g. UPDATE_PASSWORD when a credential is set as temporary). Distinct from an authentication-flow execution (chapter 25), which runs during the credential check itself rather than after it. Chapter 25 covers building custom required-action flows.", category: "Keycloak Core", chapters: ["users-and-credentials", "authentication-flows"] },
  { term: "Configure OTP (CONFIGURE_TOTP)", definition: "A required action that forces a user to enroll a one-time-password generator (via an authenticator app) before login completes. This chapter assigned it to priya.patel at creation time; chapter 5 covers the TOTP mechanics the resulting enrollment actually uses.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Update Password (UPDATE_PASSWORD)", definition: "A required action forcing a password change before login completes. Keycloak adds it automatically whenever a password is set with set-password --temporary=true — confirmed directly in this chapter's lab, where omitting --temporary left requiredActions empty and setting it to true added UPDATE_PASSWORD without any separate command.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Verify Email (VERIFY_EMAIL)", definition: "A required action Keycloak can add automatically when realm-level email verification is enabled, blocking login completion until the user confirms control of their email address. Used in this chapter's Riverside Health patient-portal case study as a different real use of the same enforcement mechanism as CONFIGURE_TOTP.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Credentials tab (Keycloak)", definition: "The Users screen's view of an identity's credentials (chapter 2's sense) — lists password and OTP credentials for a user. Backed by the Admin REST API's dedicated /users/{id}/credentials endpoint, used in this chapter to independently confirm a password credential's existence and storage format.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Password credential (Keycloak)", definition: "A credential record of type \"password\" stored under a user's credentials, holding an Argon2 hash and its parameters (iterations, memory, parallelism) rather than the password itself — confirmed directly in this chapter against jane.doe's real credentials response.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "OTP credential (Keycloak)", definition: "A credential record of type \"otp\" created once a user completes OTP enrollment, tracked separately from the password credential and reflected in the user's totp flag. Chapter 5 covers what the underlying TOTP secret and codes actually are.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Declarative User Profile", definition: "Keycloak's realm-level schema (configurable via the users/profile Admin REST resource) for defining exactly which user attributes exist and how they validate — any attribute not declared this way is an \"unmanaged attribute,\" governed by the realm's unmanagedAttributePolicy setting. By default declares only username/email/firstName/lastName. Hit directly in both chapter 22's and chapter 24's labs: a custom attribute (department) was silently dropped on write until the policy was changed.", category: "Keycloak Core", chapters: ["users-and-credentials", "clients-and-scopes"] },
  { term: "Unmanaged attribute (Keycloak)", definition: "A user attribute not declared in the realm's Declarative User Profile. By default (unmanagedAttributePolicy unset/DISABLED), writes to it are silently dropped everywhere, with no error returned — confirmed live in both chapter 22's and chapter 24's labs. Governed by the realm-level unmanagedAttributePolicy: DISABLED (default), ENABLED (allowed everywhere), ADMIN_VIEW (admin-readable only), or ADMIN_EDIT (admin-readable and writable). Keycloak's own docs recommend declaring the attribute formally, or using ADMIN_EDIT, over leaving ENABLED set broadly.", category: "Keycloak Core", chapters: ["users-and-credentials", "clients-and-scopes"] },
  { term: "User attribute (Keycloak)", definition: "The concrete Keycloak implementation of chapter 2's generic Attribute concept, split into built-in attributes every user has (username, email, firstName, lastName) and custom attributes an organization adds (e.g. department, team) — the latter subject to Declarative User Profile validation, unlike the former.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Enabled/Disabled toggle (Keycloak)", definition: "The user-representation field (enabled: true/false) that implements chapter 2's generic \"suspend\" lifecycle stage concretely — a single field flip, reversible, leaving the rest of the record (attributes, id, credential history) untouched, as distinct from kcadm.sh delete, which this chapter confirmed returns a real 404 on the next lookup.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Credential storage (hashing)", definition: "Keycloak never stores a password credential's plaintext value; it stores a hash (Argon2, confirmed live in this chapter) plus the hashing algorithm's parameters, inside the credentialData field of the credential record. Full depth on hashing/crypto choices belongs to chapter 16; this chapter only confirms what's actually in the record.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Account Console (Keycloak)", definition: "Keycloak's separate, per-realm self-service UI (at /realms/<realm>/account) where an end user — not an admin — manages their own profile, credentials, and sessions, forward-referenced by chapter 1 and made concrete here as the self-service counterpart to the admin-facing Users screen this chapter used.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Temporary credential (Keycloak)", definition: "A password credential set with kcadm.sh set-password --temporary=true, which Keycloak automatically pairs with an UPDATE_PASSWORD required action so the user must choose their own password at next login. Confirmed in this chapter by running both the temporary and non-temporary cases and inspecting requiredActions after each.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Internal user ID vs. identifier (Keycloak)", definition: "Keycloak assigns every user a server-generated UUID (the id field) used as the actual lookup key for every Admin REST API call, distinct from the human-facing username/email identifiers chapter 2 described. Both are identifiers in chapter 2's sense (unique, not secret) — they just serve different callers.", category: "Keycloak Core", chapters: ["users-and-credentials"] },
  { term: "Default required action (Keycloak)", definition: "A required action marked \"Set as default action\" under Authentication → Required Actions (REST field defaultAction), applied automatically to every new user created via Add User or self-registration, as distinct from a required action assigned to one specific user (as chapter 22 did for priya.patel). Chapter 25's lab sets CONFIGURE_TOTP's defaultAction to true for the northwind-apps realm, confirmed via a separate GET.", category: "Keycloak Core", chapters: ["users-and-credentials", "authentication-flows"] },

  { term: "Realm role", definition: "A Keycloak role that lives in the realm's own namespace and is visible to, and checkable by, every client registered in that realm — the right tool for \"what kind of identity is this,\" true regardless of which application is in use.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Client role", definition: "A Keycloak role scoped to one specific client's own namespace — per Keycloak's documentation, \"a role namespace dedicated to the client.\" The same role name can exist as a realm role and, separately, as a different client role with no collision, since each lives in its own namespace. Concretely, it's a role with clientRole: true, created under that client's own /roles resource rather than the realm's — confirmed live in chapter 24 by checking a client role never appears in the realm's own role listing.", category: "Keycloak Core", chapters: ["roles-and-groups", "clients-and-scopes"] },
  { term: "Role namespace", definition: "The scope boundary that keeps realm roles and client roles from colliding by name: the realm itself is one namespace, and each client gets its own separate one, so identical role names in different namespaces mean entirely different things.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Composite role (Keycloak)", definition: "A Keycloak role that is \"associated with\" other roles, so assigning it to a user also grants every role it contains, transitively. Configured via a role's Action menu (\"Add associated roles\"). Not the same mechanism as group-based inheritance — a composite role bundles roles; a group bundles role mappings for a set of users.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Associated roles", definition: "The set of other roles a Keycloak composite role contains — assigning the composite role to a user implicitly grants every associated role as well, without a separate assignment for each one.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Group (Keycloak)", definition: "A named collection of users that can carry its own role mappings and attributes, which every current member inherits automatically. Keycloak's own docs: \"Users that become members of a group inherit the attributes and role mappings that group defines.\" Adding or removing a membership immediately changes the member's effective, inherited access.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Subgroup", definition: "A Keycloak group created underneath an existing parent group, which inherits the parent's role mappings in addition to any role mappings defined on the subgroup itself.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Group role mapping (inherited role)", definition: "A role mapping defined on a Keycloak group rather than on an individual user. Every current member of the group inherits it automatically; it's distinct from a role assigned directly to one user, and a user's effective realm-role set is the union of both sources.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Default realm role (default-roles-<realm>)", definition: "An automatically created composite realm role (named default-roles-<realm-name>) that every user in that realm holds, bundling baseline roles like offline_access and uma_authorization. It shows up in every user's role-mapping listing and is not something a role change (Mover event) needs to add or remove.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Role mapping (Keycloak)", definition: "The association between a user (or a group) and a role it holds — the record Keycloak actually checks at an authorization decision. A user's full, effective role mapping is the union of roles assigned directly plus roles inherited from every group the user currently belongs to.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "kcadm.sh role assignment (add-roles / remove-roles)", definition: "The kcadm.sh subcommands that directly grant (add-roles) or revoke (remove-roles) a realm or client role on a specific user, identified by --uusername and --rolename. Both succeed silently; confirming the result requires a separate get on the user's role-mappings endpoint.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "kcadm.sh group membership (update / delete)", definition: "The kcadm.sh pattern for managing group membership against the Admin REST API's users/{id}/groups/{groupId} endpoint: update (a PUT) adds the user to the group, delete removes them. Both succeed silently; confirming the result requires a separate get on the user's groups endpoint.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Toxic-combination-resistant role design", definition: "A role-modeling choice that keeps a Segregation of Duties violation visible and checkable rather than hidden: defining narrow, independent roles (e.g. separate transfer-creator and transfer-approver roles) instead of one broad role that quietly bundles both abilities, so an access review can detect the dangerous combination as a simple query against role assignments rather than having to reverse-engineer a monolithic role's contents.", category: "Identity governance", chapters: ["roles-and-groups"] },
  { term: "Group-based role bundling", definition: "Using a Keycloak group's own role mappings to grant a whole team's worth of users the same role(s) in one place, instead of assigning (and later individually revoking) the same role on every member one at a time — the operational reason organizations track team membership as groups even when a role assignment alone would technically suffice.", category: "Keycloak Core", chapters: ["roles-and-groups"] },
  { term: "Northwind Apps role model (tenant-admin / support-agent / platform-engineer)", definition: "The three independent, non-composite realm roles created in chapter 23 for the northwind-apps realm: tenant-admin (full administrative access within one customer tenant), support-agent (support tooling and tenant-facing queues), and platform-engineer (platform engineering tooling and infrastructure) — kept deliberately non-overlapping so a role change between them removes access cleanly rather than leaving it nested inside a composite role.", category: "Keycloak Core", chapters: ["roles-and-groups"] },

  { term: "Client scope (Keycloak)", definition: "A named, realm-level, reusable bundle of protocol mapper configuration and role-scope mappings that can be attached to any number of clients. The concrete Keycloak object behind OAuth's abstract Scope (chapter 13) — defining one once and attaching it to many clients means a later claim change updates every one of them at once.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Default client scope", definition: "A client scope attached to a client in default mode: automatically included in every token that client requests, with no scope= parameter needed. Contrast with optional client scope.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Optional client scope", definition: "A client scope attached to a client in optional mode: only included in a token if the request's own scope= parameter names it explicitly. Contrast with default client scope.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Protocol mapper", definition: "A single Keycloak rule, attached to a client scope (or directly to a client), that decides one claim: where its value comes from (a user attribute, a hardcoded value, a role name, a group membership) and which token types/responses it's allowed into, via independent id.token.claim/access.token.claim/userinfo.token.claim flags. The concrete mechanism behind OIDC custom claims (chapter 15).", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "User attribute mapper (oidc-usermodel-attribute-mapper)", definition: "The specific Keycloak protocol mapper type that reads a named Keycloak user attribute and writes its value under a chosen claim name. Requires the source attribute to actually be persisted on the user — a declarative User Profile that hasn't declared or enabled that attribute will silently produce no claim at all, with no error anywhere in the chain.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Confidential client (Keycloak)", definition: "A Keycloak client with publicClient: false, issued an auto-generated client secret that must be presented at the token endpoint. Meant for applications that run somewhere an attacker cannot read the source — a backend/server-rendered app, not a browser SPA or a decompiled mobile binary.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Public client (Keycloak)", definition: "A Keycloak client with publicClient: true, issued no client secret at all. Relies on PKCE (chapter 13) rather than a secret to protect its authorization code exchange — the correct configuration for a browser SPA or native/mobile app, where any embedded secret would be readable by anyone.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Client secret (Keycloak)", definition: "An auto-generated credential issued only to confidential clients, required alongside an authorization code (or other grant parameters) at the token endpoint. Retrievable via the Admin REST API/kcadm.sh (GET .../client-secret) or the Admin Console's Credentials tab — never meant to be embedded in code an attacker could read.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Standard flow (Keycloak client setting)", definition: "The standardFlowEnabled client toggle controlling whether this client may use the authorization code grant (chapter 13) at all. A client needs at least one grant-type toggle enabled to obtain tokens through any means.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Direct access grants (Keycloak client setting)", definition: "The directAccessGrantsEnabled client toggle controlling whether this client may use the Resource Owner Password Credentials grant (chapter 13's deprecated ROPC) directly, trading a username/password for tokens with no redirect at all. Discouraged for real applications; useful only as a lab/testing technique to mint a token without a browser.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Service accounts (Keycloak client setting)", definition: "The serviceAccountsEnabled client toggle controlling whether this client gets its own dedicated service-account user and may use the client credentials grant (chapter 13/14) for machine-to-machine access with no human resource owner involved.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "unmanagedAttributePolicy", definition: "A realm-level User Profile setting controlling whether attributes outside the declared schema are persisted at all. Unset (the effective default), such attributes are silently dropped on write; ENABLED (or an admin-only variant) allows them to be stored and later read by protocol mappers.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Default client scopes (client relationship)", definition: "The list of client scopes a given Keycloak client has attached in default mode, retrievable via GET clients/<id>/default-client-scopes. Includes Keycloak's own built-in scopes (profile, email, roles, web-origins, acr, basic) alongside any custom scopes an admin attaches, such as northwind-profile in chapter 24.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Web origins (Keycloak client field)", definition: "A Keycloak client field listing browser origins allowed to make CORS requests against Keycloak endpoints on this client's behalf. Separate from Valid Redirect URIs — redirect URIs control where the browser is sent after login; Web Origins controls which origins' JavaScript may call Keycloak's APIs directly.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Consent screen attribute (client scope)", definition: "A client scope's display.on.consent.screen attribute, controlling whether that scope's claims are listed to the user on a consent prompt before being granted. Separate from include.in.token.scope, which controls whether the scope's name itself appears in the issued token's own scope claim.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "jsonType.label (protocol mapper config)", definition: "A protocol mapper config field declaring how to type a claim's value in the issued JSON payload — String, long, boolean, or JSON — independent of how the underlying Keycloak user attribute itself is stored (always as a string or list of strings).", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "multivalued (protocol mapper config)", definition: "A protocol mapper config boolean controlling whether a claim's value is always rendered as a JSON array, even when the underlying attribute has only one value — false renders a single value as a bare scalar instead.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Introspection token claim (protocol mapper config)", definition: "A protocol mapper config flag (introspection.token.claim) controlling whether this mapper's claim also appears in RFC 7662 token introspection responses (chapter 14), independent of the id.token.claim/access.token.claim/userinfo.token.claim flags that control the token/UserInfo paths.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Client ID vs. internal id (Keycloak)", definition: "A Keycloak client has two distinct identifiers: clientId, the human-chosen, OAuth-facing name (e.g. northwind-dashboard) used in authorize/token requests, and a separate internal UUID (Keycloak's own primary key) used in every Admin REST API path (clients/<uuid>/...). Confusing the two is a common kcadm.sh/REST scripting mistake.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Exclusive redirect URI pattern", definition: "Keycloak's own recommended practice (named directly in its Server Administration Guide) of registering the narrowest possible Valid Redirect URIs pattern for a client — a full path, or at most a trailing wildcard scoped to one specific subpath — rather than a broad or bare wildcard, to minimize the blast radius chapter 13's exact-match lesson warns about.", category: "Keycloak core", chapters: ["clients-and-scopes"] },
  { term: "Resource owner password credentials as a lab technique", definition: "Using the deprecated ROPC/direct-access-grants flow deliberately and temporarily, in a disposable lab environment only, to mint a real token for a real user without needing a browser — explicitly not a recommended pattern for any real application (chapter 13), reverted immediately after use in chapter 24's lab.", category: "Keycloak core", chapters: ["clients-and-scopes"] },

  { term: "Authentication flow (Keycloak)", definition: "A realm-scoped, ordered tree of executions that decides what proof is demanded during a protocol-level action — browser login, direct grant, registration, and so on. Every realm ships five built-in top-level flows for these purposes (plus client-authentication and Docker-registry flows), and any of them can be cloned into an independently editable custom flow.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Execution (authentication flow)", definition: "One node in a Keycloak authentication flow's tree — either a single authenticator (e.g. Username Password Form, OTP Form) or a nested subflow containing more executions. Each execution carries its own requirement level and ordering (level/index/priority in the Admin REST API).", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Requirement level (REQUIRED / ALTERNATIVE / CONDITIONAL / DISABLED)", definition: "The four values a Keycloak flow execution can take: REQUIRED must succeed; ALTERNATIVE is one of several acceptable paths at that level; CONDITIONAL (subflows only) is evaluated at all only if every REQUIRED condition execution directly inside it evaluates true first; DISABLED is never evaluated. Which levels an execution can actually take is constrained by its own requirementChoices.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Browser flow (Keycloak)", definition: "The built-in top-level flow bound to standard interactive web login (a redirect to a login page). The realm's browserFlow setting selects which top-level flow actually plays this role, defaulting to the built-in alias \"browser\".", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Direct Grant flow (Keycloak)", definition: "The built-in flow executed for API-style, non-interactive logins (e.g. the resource-owner-password-credentials shape), where credentials arrive directly in a token request rather than via a redirected login page.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Registration flow (Keycloak)", definition: "The built-in flow governing self-service account creation via the login page's \"Register\" link — a distinct process from logging in, with its own steps such as terms-and-conditions and profile capture.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Reset Credentials flow (Keycloak)", definition: "The built-in flow governing the forgot-password / account-recovery process, bound to the realm via resetCredentialsFlow.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "First Broker Login flow (Keycloak)", definition: "The built-in flow that runs exactly once per user, the first time they authenticate through a brokered external identity provider — before Keycloak has decided whether to link, create, or reject a local account for them. Distinct from every ordinary login flow.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Conditional subflow", definition: "A subflow whose own requirement level is CONDITIONAL. Keycloak only evaluates (and potentially requires) its children if every REQUIRED condition-type execution directly inside it evaluates true first; multiple REQUIRED conditions in the same subflow are implicitly ANDed, and if any required condition fails, the whole subflow — and everything nested in it — is skipped outright.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Condition - user configured (authenticator)", definition: "A condition execution (provider conditional-user-configured) that evaluates true only if the authenticating user already has a credential configured for at least one authenticator later in the same subflow. Keycloak's own default browser flow uses this to ask returning MFA users for their second factor without demanding brand-new users enroll one mid-login.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Condition - user role (authenticator)", definition: "A condition execution (provider conditional-user-role) that evaluates true only if the authenticating user holds a specified realm or client role, configured via a single condUserRole value (optionally negated). The mechanism this course uses to gate OTP specifically to Northwind Apps's tenant-admin role rather than to every user.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Flow duplication (Keycloak)", definition: "Copying an entire built-in flow, including its full subflow tree, into a new, independently editable top-level flow — via the Admin Console's \"Duplicate\" action or the Admin REST API's POST .../copy endpoint. Required because built-in flows themselves cannot be edited in place, only copied and then modified.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Built-in flow (Keycloak)", definition: "One of the flows Keycloak creates automatically in every new realm (browser, direct grant, registration, reset credentials, clients, first broker login, plus docker auth). Shown read-only in the Admin Console specifically so a safe, known-good default always exists to fall back to or clone from.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Flow binding (realm)", definition: "The realm-level settings (browserFlow, registrationFlow, directGrantFlow, resetCredentialsFlow, clientAuthenticationFlow, firstBrokerLoginFlow, dockerAuthenticationFlow) that select which top-level flow actually runs for each purpose. Cloning a flow has no effect on real logins until the realm is rebound to the clone's alias.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Conditional OTP (step-up pattern)", definition: "Configuring OTP's authenticator execution inside a CONDITIONAL subflow instead of as a flat REQUIRED/ALTERNATIVE step in the main flow, so the possession factor (OTP) is demanded only when a condition — role membership, prior enrollment, client scope, risk signal — says it should be. The concrete Keycloak mechanism behind step-up authentication.", category: "Keycloak Core", chapters: ["authentication-flows"] },
  { term: "Authenticator SPI", definition: "Keycloak's pluggable provider interface for writing custom authenticators and conditions in Java (e.g. a transaction-context-aware condition a bank like Meridian Trust would need for action-triggered step-up, which no built-in condition provider covers). Forward-pointer to chapters 39-40; chapter 25 only used built-in providers (conditional-user-role, conditional-user-configured).", category: "Keycloak Core", chapters: ["authentication-flows"] },

  { term: "Theme (Keycloak)", definition: "A named bundle of templates, stylesheets, and message bundles that controls how a category of Keycloak screen looks and speaks. Themes are assigned per realm (login/account/admin/email) or per instance (welcome), and Keycloak 26.x ships its built-in ones (base, keycloak, keycloak.v2) inside a JAR rather than as a plain editable directory.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Login theme", definition: "The realm theme setting (REST field loginTheme) controlling username/password entry, OTP entry, registration, and similar login-adjacent screens — the one every lab chapter since 20 has been implicitly hitting.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Account theme", definition: "The realm theme setting (REST field accountTheme) controlling the self-service Account Console a user manages their own profile, credentials, and sessions through.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Admin console theme", definition: "The realm theme setting (REST field adminTheme) controlling the skin of the Keycloak Admin Console itself, distinct from the login or account screens an ordinary user sees.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Email theme", definition: "The realm theme setting (REST field emailTheme) controlling the templates used for every email Keycloak sends — verification, password reset, OTP codes.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Welcome theme", definition: "The instance-wide default page shown at Keycloak's root URL with no realm context. Unlike the four realm-level theme fields, it is configured via a server startup option (--spi-theme--welcome-theme=<name>), not a per-realm REST field.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Theme type", definition: "One of the categories a Keycloak theme can provide templates/resources for — login, account, admin, email, welcome, or common (shared resources imported by others). A single theme name (e.g. keycloak) may implement several types but not necessarily all of them.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "theme.properties", definition: "The configuration file inside a theme type's directory (themes/<name>/<type>/theme.properties) that declares what the theme extends (parent=), imports (import=), its stylesheets, and whether it's abstract — confirmed by reading the real files inside Keycloak 26.8.2's bundled themes jar for this chapter.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Parent theme (theme inheritance)", definition: "A theme declared via parent=<name> in theme.properties that the current theme extends, inheriting its templates and resources except where explicitly overridden. Keycloak's own keycloak and keycloak.v2 themes both declare parent=base.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Abstract theme", definition: "A theme whose theme.properties sets abstract=true, marking it as meant only to be inherited from, not selected directly — Keycloak's own base theme is abstract. The Admin Console's Themes-tab dropdown hides abstract themes from direct selection, but this is a UI-level courtesy only: the Admin REST API does not enforce it, and will accept an abstract theme name as a realm's theme setting without complaint.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "FTL template override", definition: "A Freemarker (.ftl) template file placed at the exact relative path of a parent theme's own template (e.g. login/login.ftl) inside a custom theme directory, shadowing it. Only needed when a screen's markup itself must change, not merely its styling, which is handled through CSS/resources instead.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Theme caching", definition: "Keycloak's practice of caching compiled theme templates and static resources for performance. Disabled by default under start-dev (and via explicit --spi-theme--cache-themes=false/--spi-theme--cache-templates=false options) so edits appear without a restart; left enabled in production, where disabling it significantly impacts performance per Keycloak's own UI Customization Guide.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Internationalization (i18n, Keycloak realm setting)", definition: "A realm-level feature (REST field internationalizationEnabled, default false) that, once enabled alongside supportedLocales and defaultLocale, lets Keycloak's login/account/admin/email screens render in multiple languages rather than only the theme's default locale.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "supportedLocales", definition: "The realm REST field listing which locale codes a realm offers once internationalization is enabled. Declaring a locale here does not by itself guarantee translated text exists for it — that depends on a theme actually shipping a matching messages_<locale>.properties file.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "defaultLocale (realm setting)", definition: "The realm REST field naming which locale to fall back to when no higher-priority signal (user selection, user profile, client request, cookie, browser Accept-Language header) resolves one, second-to-last in Keycloak's documented locale resolution order before English itself.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Locale resolution order", definition: "Keycloak's documented sequence for picking which language to render: user-selected on the login page, then user-profile locale, then a client-requested locale (e.g. OIDC's ui_locales parameter), then a cookie, then the browser's Accept-Language header, then the realm's defaultLocale, then English as the final fallback. A custom LocaleSelectorProvider SPI can replace this order entirely.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Message bundle (theme)", definition: "A locale-specific .properties file (messages_<locale>.properties) inside a theme's messages/ directory supplying translated text for ${msg(\"key\")} references in templates. Keycloak's base theme ships dozens of built-in locale bundles out of the box; a provider can also contribute its own theme-resources/messages/messages_en.properties that gets merged into every theme's bundle.", category: "Theming & Localization", chapters: ["themes-and-branding"] },
  { term: "Theme-resources (provider-contributed)", definition: "FTL templates, stylesheets, and message bundles that a custom SPI provider (e.g. a custom authenticator) ships inside its own JAR under theme-resources/, which Keycloak merges into whichever theme a realm is actually using at render time, rather than requiring the provider to fork the theme itself.", category: "Theming & Localization", chapters: ["themes-and-branding"] }
];
